async fn handle_delegate_task(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let sender_id = params.get("sender_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing sender_id".to_string(),
            data: None,
        })?;

    let receiver_id = params.get("receiver_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing receiver_id".to_string(),
            data: None,
        })?;

    let task_type = params.get("task_type")
        .and_then(|v| v.as_str())
        .unwrap_or("GenericTask")
        .to_string();

    let parameters: std::collections::HashMap<String, serde_json::Value> = params
        .get("parameters")
        .and_then(|v| v.as_object())
        .map(|obj| obj.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
        .unwrap_or_default();

    let agent_runtime = node.agent_runtime().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Agent runtime not initialized".to_string(),
        data: None,
    })?;

    use tenzro_types::agent::AgentIdentity;
    use tenzro_types::primitives::Address;

    let sender_identity = AgentIdentity::new(
        sender_id.to_string(),
        Address::zero(),
        sender_id.to_string(),
        Address::zero(),
    );

    let receiver_identity = AgentIdentity::new(
        receiver_id.to_string(),
        Address::zero(),
        receiver_id.to_string(),
        Address::zero(),
    );

    let task_id = agent_runtime
        .delegate_task(sender_identity, receiver_identity, task_type.clone(), parameters)
        .await
        .map_err(|e| JsonRpcError { code: -32000, message: format!("Failed to delegate task: {}", e), data: None })?;

    // Wire TNZO billing: flat 0.001 TNZO delegation fee from caller to receiver
    const DELEGATION_FEE_WEI: u128 = 1_000_000_000_000_000; // 0.001 TNZO
    if let Some(token) = node.token()
        && let Some(caller_str) = params.get("caller_address").and_then(|v| v.as_str())
            && let Ok(caller_addr) = parse_address(caller_str)
                && let Some(receiver_str) = params.get("receiver_address").and_then(|v| v.as_str())
                    && let Ok(receiver_addr) = parse_address(receiver_str) {
                        if let Err(e) = token.transfer(&caller_addr, &receiver_addr, DELEGATION_FEE_WEI) {
                            tracing::warn!(
                                sender = %sender_id,
                                receiver = %receiver_id,
                                "Delegation fee billing failed: {}",
                                e
                            );
                        } else {
                            tracing::info!(
                                sender = %sender_id,
                                receiver = %receiver_id,
                                fee_wei = %DELEGATION_FEE_WEI,
                                "Delegation fee charged"
                            );
                        }
                    }

    Ok(serde_json::json!({
        "task_id": task_id,
        "sender_id": sender_id,
        "receiver_id": receiver_id,
        "task_type": task_type,
        "status": "delegated",
    }))
}

/// Returns the faucet's signing address and current balance for diagnostics.
/// No params, no auth required (read-only).
async fn handle_faucet_info(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let storage = node.storage().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Storage not initialized".to_string(),
        data: None,
    })?;

    let address_hex = match storage.get("metadata", crate::genesis::FAUCET_SIGNING_KEY_ADDRESS) {
        Ok(Some(bytes)) => String::from_utf8(bytes).map_err(|_| JsonRpcError {
            code: -32000,
            message: "Faucet signing address is not valid UTF-8 hex".to_string(),
            data: None,
        })?,
        _ => return Err(JsonRpcError {
            code: -32000,
            message: "Faucet signing address not provisioned".to_string(),
            data: None,
        }),
    };

    let faucet_addr = tenzro_types::primitives::Address::from_hex(&address_hex)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Invalid persisted faucet address: {}", e),
            data: None,
        })?;

    // Read balance from CF_ACCOUNTS (TnzoToken layout: "balance:" + address bytes).
    let mut balance_key = b"balance:".to_vec();
    balance_key.extend_from_slice(faucet_addr.as_bytes());
    let balance: u128 = match storage.get("accounts", &balance_key) {
        Ok(Some(bytes)) if bytes.len() == 16 => {
            let arr: [u8; 16] = bytes.try_into().unwrap();
            u128::from_le_bytes(arr)
        }
        _ => 0,
    };

    // Also read legacy sentinel address balance for diagnostics.
    let legacy_addr_hex: Option<String> = match storage.get("metadata", b"genesis_faucet_address") {
        Ok(Some(bytes)) => String::from_utf8(bytes).ok(),
        _ => None,
    };

    Ok(serde_json::json!({
        "address": format!("0x{}", address_hex),
        "balance_wei": balance.to_string(),
        "legacy_genesis_pointer": legacy_addr_hex.map(|h| format!("0x{}", h)),
    }))
}

async fn handle_faucet(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let address_str = params.get("address")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing address".to_string(),
            data: None,
        })?;

    // Default 10,000 TNZO (= 10_000 * 10^18 wei); caller may request up
    // to the same amount. This is the testnet starter-allotment so every
    // new wallet has enough TNZO to actually use the network — chat with
    // model providers, deposit for validation, contribute to training —
    // without immediately running into a low-balance wall. Bumped from
    // the historical 100/1000 defaults when Tenzro Studio's onboarding
    // started auto-faucet'ing new wallets on creation. Per-address 24h
    // cooldown (below) still rate-limits abuse.
    //
    // `amount_wei` accepts a u64 number (small values) or a decimal
    // string (large values, since 10_000 TNZO = 10^22 wei overflows u64).
    const DEFAULT_FAUCET_WEI: u128 = 10_000 * 1_000_000_000_000_000_000u128;
    const MAX_FAUCET_WEI: u128 = 10_000 * 1_000_000_000_000_000_000u128;
    let amount_wei: u128 = match params.get("amount_wei") {
        Some(v) => {
            if let Some(n) = v.as_u64() {
                (n as u128).min(MAX_FAUCET_WEI)
            } else if let Some(s) = v.as_str() {
                s.parse::<u128>()
                    .map_err(|_| JsonRpcError {
                        code: -32602,
                        message: format!("Invalid amount_wei: '{}' is not a valid u128", s),
                        data: None,
                    })?
                    .min(MAX_FAUCET_WEI)
            } else {
                return Err(JsonRpcError {
                    code: -32602,
                    message: "amount_wei must be a u64 number or decimal string".to_string(),
                    data: None,
                });
            }
        }
        None => DEFAULT_FAUCET_WEI,
    };

    // Parse recipient address
    let to_addr = parse_address(address_str).map_err(|_| JsonRpcError {
        code: -32602,
        message: format!("Invalid address: {}", address_str),
        data: None,
    })?;

    // Storage is needed for both cooldown enforcement and key loading.
    let storage = node.storage().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Storage not initialized".to_string(),
        data: None,
    })?;

    // Per-address cooldown enforcement. Reads `cooldown_seconds` from genesis
    // FaucetConfig (default 86400 = 24h). Uses the same `faucet_request:<addr>`
    // CF_METADATA keyspace as the web `/api/faucet` handler so a single
    // address cannot bypass cooldown by switching transports.
    let cooldown_secs: i64 = node
        .config()
        .genesis
        .as_ref()
        .and_then(|g| g.faucet.as_ref().map(|f| f.cooldown_seconds as i64))
        .unwrap_or(86400);
    if cooldown_secs > 0 {
        let now_ts = chrono::Utc::now().timestamp();
        let addr_key_lower = address_str
            .strip_prefix("0x")
            .unwrap_or(address_str)
            .to_lowercase();
        let faucet_key = format!("faucet_request:{}", addr_key_lower);
        if let Ok(Some(bytes)) = storage.get("metadata", faucet_key.as_bytes()) {
            if bytes.len() == 8 {
                let arr: [u8; 8] = bytes.as_slice().try_into().unwrap_or([0; 8]);
                let last_ts = i64::from_le_bytes(arr);
                let elapsed = now_ts - last_ts;
                if elapsed < cooldown_secs {
                    let remaining = cooldown_secs - elapsed;
                    return Err(JsonRpcError {
                        code: -32004,
                        message: format!(
                            "Faucet cooldown active for address. Try again in {} seconds.",
                            remaining
                        ),
                        data: Some(serde_json::json!({
                            "cooldown_seconds": cooldown_secs,
                            "elapsed_seconds": elapsed,
                            "remaining_seconds": remaining,
                        })),
                    });
                }
            }
        }
    }

    let privkey_hex = match storage.get("metadata", crate::genesis::FAUCET_SIGNING_KEY_PRIVATE) {
        Ok(Some(bytes)) => String::from_utf8(bytes).map_err(|_| JsonRpcError {
            code: -32000,
            message: "Faucet signing key is not valid UTF-8 hex".to_string(),
            data: None,
        })?,
        _ => return Err(JsonRpcError {
            code: -32000,
            message: "Faucet signing key not provisioned. The node must complete genesis bootstrap before serving faucet requests.".to_string(),
            data: None,
        }),
    };

    let address_hex = match storage.get("metadata", crate::genesis::FAUCET_SIGNING_KEY_ADDRESS) {
        Ok(Some(bytes)) => String::from_utf8(bytes).map_err(|_| JsonRpcError {
            code: -32000,
            message: "Faucet signing address is not valid UTF-8 hex".to_string(),
            data: None,
        })?,
        _ => return Err(JsonRpcError {
            code: -32000,
            message: "Faucet signing address not provisioned".to_string(),
            data: None,
        }),
    };

    let faucet_addr = tenzro_types::primitives::Address::from_hex(&address_hex)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Invalid persisted faucet address: {}", e),
            data: None,
        })?;

    // Build + sign the faucet transfer as a real transaction. Signature is an
    // Ed25519 signature over SHA-256(Transaction), produced server-side with
    // the faucet's own secret key (never exposed to the caller). Submitted to
    // the event loop so it enters the mempool, gossips, and is finalized
    // identically across all validators.
    let sk_bytes = hex::decode(&privkey_hex).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Faucet private key is not valid hex: {}", e),
        data: None,
    })?;
    let secret_key = tenzro_crypto::SecretKey::new(KeyType::Ed25519, sk_bytes);
    let keypair = KeyPair::from_secret_key(secret_key).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Failed to load faucet keypair: {}", e),
        data: None,
    })?;
    let pubkey_bytes = keypair.public_key().as_bytes().to_vec();

    // Nonce tracking for the faucet. The authoritative source is the VM
    // execution-state nonce (CF_STATE, `nonce:<hex(addr)>`) — the same value
    // `MultiVmRuntime` validates `tx.nonce` against. The in-memory `peek_nonce`
    // counter resets to 0 on every node restart, so relying on it alone makes
    // the first post-restart faucet tx revert with `Invalid nonce: expected N,
    // got 0`. We read the VM-state nonce as the floor and take the max with the
    // wallet's atomically-reserved counter so concurrent same-block requests
    // still receive distinct nonces.
    let chain_nonce = {
        let state = tenzro_vm::StateAdapter::with_storage(
            storage.clone() as std::sync::Arc<dyn tenzro_storage::KvStore>,
        );
        use tenzro_vm::traits::VmState as _;
        state.get_nonce(faucet_addr.as_bytes())
    };
    let wallet_service = node.wallet_service();
    let nonce = match &wallet_service {
        Some(ws) => {
            use tenzro_wallet::WalletService;
            let reserved = ws.next_nonce(&faucet_addr);
            if reserved.0 >= chain_nonce { reserved } else { Nonce::from(chain_nonce) }
        }
        None => Nonce::from(chain_nonce),
    };

    let chain_id = node.config().genesis.as_ref().map(|g| g.chain_id).unwrap_or(1337);
    // Load the faucet's persistent ML-DSA-65 signing key. The seed is
    // provisioned once at first boot by `provision_faucet_signing_key()`
    // (with back-fill for classical-only state), so this lookup is mandatory —
    // there is no per-request keygen fallback.
    let pq_seed_hex = match storage.get("metadata", crate::genesis::FAUCET_PQ_SIGNING_SEED) {
        Ok(Some(bytes)) => String::from_utf8(bytes).map_err(|_| JsonRpcError {
            code: -32000,
            message: "Faucet PQ seed is not valid UTF-8 hex".to_string(),
            data: None,
        })?,
        _ => return Err(JsonRpcError {
            code: -32000,
            message: "Faucet PQ signing key not provisioned".to_string(),
            data: None,
        }),
    };
    let pq_seed_bytes = hex::decode(&pq_seed_hex).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Faucet PQ seed is not valid hex: {}", e),
        data: None,
    })?;
    let pq_signing_key = tenzro_crypto::pq::MlDsaSigningKey::from_seed(&pq_seed_bytes)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Failed to derive faucet PQ key: {}", e),
            data: None,
        })?;
    // Gas price must clear the Open-lane fee floor — the faucet account
    // has no registered DID so admission lands it in Open lane, which
    // requires `mempool_min_gas_price × open_floor_mult` = 1 gwei × 4.0 =
    // 4 gwei. The fee is paid back to the network treasury, so it's a
    // book-keeping no-op for the operator.
    let tx = Transaction::new(
        ChainId::from(chain_id),
        faucet_addr,
        to_addr,
        nonce,
        TransactionType::Transfer { amount: amount_wei },
        21000,
        4_000_000_000,
        pq_signing_key.verifying_key_bytes().to_vec(),
    );

    let tx_hash = tx.hash();

    // Sign the canonical tx hash. We use the raw Ed25519 signer directly
    // (not the MPC wallet service) because the faucet key is a plain Ed25519
    // key, not a threshold-shared MPC wallet.
    use tenzro_crypto::signatures::Signer;
    let signer = tenzro_crypto::signatures::Ed25519SignerImpl::new(keypair).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Faucet signer init failed: {}", e),
        data: None,
    })?;
    let crypto_sig = signer.sign(tx_hash.as_bytes()).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Faucet signing failed: {}", e),
        data: None,
    })?;

    let pq_sig = pq_signing_key.sign(tx_hash.as_bytes()).to_vec();
    let signed_tx = SignedTransaction::new(
        tx,
        Signature::new(crypto_sig.to_bytes(), pubkey_bytes),
        pq_sig,
    );
    let tx_hash_out = signed_tx.clone().hash();
    let tx_hash_str = format!("{}", tx_hash_out);

    // Synchronously admit the faucet tx to the consensus mempool first, then
    // dispatch a `LocallyAdmittedTransaction` event for gossip propagation
    // only. This mirrors the `eth_sendRawTransaction` pattern: callers see
    // mempool errors (fee floor, rate limit) immediately as JSON-RPC errors,
    // and the event loop skips re-admission so we don't double-charge the
    // bucket. Crucially, this is the path that survives the gossip-storm fix
    // in `event_loop::handle_new_transaction` — that handler no longer
    // re-broadcasts received txs, so faucet txs that go through `NewTransaction`
    // would never reach validators. `LocallyAdmittedTransaction` always gossips.
    if let Some(consensus) = node.consensus() {
        match consensus.submit_transaction(signed_tx.clone()) {
            Ok(()) => {
                debug!(
                    target: "rpc",
                    tx_hash = %tx_hash_out,
                    "tenzro_faucet: admitted to consensus mempool synchronously"
                );
            }
            Err(tenzro_consensus::ConsensusError::RateLimited {
                lane,
                retry_after_ms,
                burst_remaining,
                current_rate,
            }) => {
                warn!(
                    target: "rpc",
                    tx_hash = %tx_hash_out,
                    lane,
                    retry_after_ms,
                    burst_remaining,
                    current_rate,
                    "tenzro_faucet: rejected by per-DID admission (-32011)"
                );
                return Err(JsonRpcError {
                    code: -32011,
                    message: format!(
                        "Rate limit exceeded for {} lane: retry after {}ms (refill {:.3}/s)",
                        lane, retry_after_ms, current_rate
                    ),
                    data: Some(serde_json::json!({
                        "lane": lane,
                        "retryAfterMs": retry_after_ms,
                        "burstRemaining": burst_remaining,
                        "refillPerSec": current_rate,
                    })),
                });
            }
            Err(tenzro_consensus::ConsensusError::FeeFloorTooLow {
                lane,
                gas_price,
                required,
                base,
                multiplier,
            }) => {
                warn!(
                    target: "rpc",
                    tx_hash = %tx_hash_out,
                    lane,
                    gas_price,
                    required,
                    base,
                    multiplier,
                    "tenzro_faucet: rejected by lane fee floor (-32012)"
                );
                return Err(JsonRpcError {
                    code: -32012,
                    message: format!(
                        "Fee floor not met for {} lane: gas_price {} < required {} ({:.2}× base {})",
                        lane, gas_price, required, multiplier, base
                    ),
                    data: Some(serde_json::json!({
                        "lane": lane,
                        "gasPrice": gas_price,
                        "required": required,
                        "baseFloor": base,
                        "laneMultiplier": multiplier,
                    })),
                });
            }
            Err(e) => {
                warn!(
                    target: "rpc",
                    tx_hash = %tx_hash_out,
                    error = %e,
                    "tenzro_faucet: consensus mempool rejected transaction"
                );
                return Err(JsonRpcError {
                    code: -32000,
                    message: format!("Mempool rejected transaction: {}", e),
                    data: None,
                });
            }
        }
    }

    // Dispatch to event loop for gossip propagation only (admission already
    // done above when consensus is wired).
    let event_sender = node.event_sender().ok_or_else(|| {
        error!(target: "rpc", tx_hash = %tx_hash_out, "tenzro_faucet: node event loop not running");
        JsonRpcError {
            code: -32000,
            message: "Node event loop not running".to_string(),
            data: None,
        }
    })?;

    let event = if node.consensus().is_some() {
        NodeEvent::LocallyAdmittedTransaction(signed_tx)
    } else {
        // No consensus engine wired (light client / boot phase) — fall back
        // to the full event-loop path so the tx still gets locally queued.
        NodeEvent::NewTransaction(signed_tx)
    };

    event_sender
        .send(event)
        .await
        .map_err(|e| {
            error!(
                target: "rpc",
                tx_hash = %tx_hash_out,
                error = %e,
                "tenzro_faucet: failed to enqueue tx for event loop"
            );
            JsonRpcError {
                code: -32000,
                message: format!("Failed to submit faucet tx: {}", e),
                data: None,
            }
        })?;

    // Advance the nonce only after successful enqueue so concurrent retries
    // don't skip a slot.
    if let Some(ws) = &wallet_service {
        use tenzro_wallet::WalletService;
        let _ = ws.next_nonce(&faucet_addr);
    }

    // Persist cooldown timestamp under the same `faucet_request:<addr>` key
    // namespace as the web `/api/faucet` handler. Written only after the tx
    // has been admitted + enqueued so a failed request doesn't lock out the
    // address. Persisted (not in-memory) so it survives node restart.
    if cooldown_secs > 0 {
        let now_ts = chrono::Utc::now().timestamp();
        let addr_key_lower = address_str
            .strip_prefix("0x")
            .unwrap_or(address_str)
            .to_lowercase();
        let faucet_key = format!("faucet_request:{}", addr_key_lower);
        let ts_bytes = now_ts.to_le_bytes();
        let _ = storage.put(
            "metadata",
            faucet_key.as_bytes(),
            &ts_bytes,
        );
    }

    info!(
        target: "rpc",
        recipient = %address_str,
        amount_wei = %amount_wei,
        tx = %tx_hash_str,
        "tenzro_faucet: signed + enqueued via consensus path"
    );

    // The faucet tx has been signed and admitted to the mempool, but it is
    // not yet finalized. Callers must poll `eth_getBalance` (or
    // `eth_getTransactionReceipt(tx_hash)`) to confirm the transfer landed —
    // an unhealthy consensus path can leave the tx queued indefinitely. The
    // response wording reflects that distinction explicitly: "submitted",
    // not "dispensed".
    Ok(serde_json::json!({
        "submitted": true,
        "status": "queued",
        "tx_hash": tx_hash_str,
        "amount_wei": amount_wei.to_string(),
        "recipient": address_str,
        "message": format!(
            "{} wei submitted to mempool. Poll eth_getBalance({}) to confirm finalization.",
            amount_wei, address_str
        ),
    }))
}

/// Returns a structured deprecation error for the legacy escrow write RPCs.
///
/// The previous `tenzro_createEscrow` / `tenzro_releaseEscrow` handlers were
/// removed in favor of consensus-mediated, signature-verified escrow
/// transactions. Callers must build a `CreateEscrow` / `ReleaseEscrow` /
/// `RefundEscrow` transaction with `tenzro_wallet::TransactionBuilder`, sign
/// it, and submit via `eth_sendRawTransaction` (or use
/// `tenzro_signAndSendTransaction` for server-side signing).
fn handle_escrow_write_deprecated(method: &str) -> std::result::Result<Value, JsonRpcError> {
    Err(JsonRpcError {
        code: -32601,
        message: format!(
            "{} is removed. Build and sign a CreateEscrow/ReleaseEscrow/RefundEscrow \
             transaction and submit via eth_sendRawTransaction or \
             tenzro_signAndSendTransaction. Read-only escrow RPCs (tenzro_getEscrow, \
             tenzro_listEscrowsByPayer, tenzro_listEscrowsByPayee) remain available.",
            method
        ),
        data: None,
    })
}

/// Render an `EscrowAccount` as JSON for read-only RPC responses.
///
/// Wire convention: 32-byte ids and addresses are emitted as `0x`-prefixed
/// lowercase hex, matching `tx_hash` / `block_hash` / address fields elsewhere
/// in the JSON-RPC surface. Internal DashMap / RocksDB keys remain bare hex —
/// callers should not depend on the storage-key form.
fn escrow_to_json(escrow: &tenzro_settlement::EscrowAccount) -> Value {
    serde_json::json!({
        "escrow_id": format!("0x{}", escrow.escrow_id),
        "payer": format!("0x{}", hex::encode(escrow.payer.as_bytes())),
        "payee": format!("0x{}", hex::encode(escrow.payee.as_bytes())),
        "amount": escrow.amount.to_string(),
        "asset_id": escrow.asset_id,
        "status": format!("{:?}", escrow.status),
        "created_at": escrow.created_at.as_millis(),
        "expires_at": escrow.expires_at.as_millis(),
        "release_conditions": escrow.release_conditions,
    })
}

/// `tenzro_getEscrow` — read a single escrow record by id (hex-encoded 32-byte
/// digest derived by the VM during `CreateEscrow`).
async fn handle_get_escrow(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let escrow_id_raw = params
        .get("escrow_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing escrow_id".to_string(),
            data: None,
        })?;
    // The wire convention is `0x`-prefixed hex (matches what `escrow_to_json`
    // emits), but the in-memory / RocksDB key is bare hex. Strip on input so
    // both forms accept.
    let escrow_id = escrow_id_raw.strip_prefix("0x").unwrap_or(escrow_id_raw);

    let escrow_manager = node.escrow_manager().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Escrow manager not initialized".to_string(),
        data: None,
    })?;

    let escrow = escrow_manager.get_escrow(escrow_id).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Escrow lookup failed: {}", e),
        data: None,
    })?;

    Ok(escrow_to_json(&escrow))
}

/// `tenzro_listEscrowsByPayer` — list all escrows for a given payer address.
async fn handle_list_escrows_by_payer(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let payer_hex = params
        .get("payer")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing payer address".to_string(),
            data: None,
        })?;
    let payer = parse_address(payer_hex)?;

    let escrow_manager = node.escrow_manager().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Escrow manager not initialized".to_string(),
        data: None,
    })?;

    let escrows = escrow_manager.get_escrows_by_payer(&payer);
    Ok(serde_json::json!({
        "payer": payer_hex,
        "count": escrows.len(),
        "truncated": escrows.len() > LIST_RESPONSE_CAP,
        "escrows": escrows.iter().take(LIST_RESPONSE_CAP).map(escrow_to_json).collect::<Vec<_>>(),
    }))
}

/// `tenzro_listEscrowsByPayee` — list all escrows for a given payee address.
async fn handle_list_escrows_by_payee(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let payee_hex = params
        .get("payee")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing payee address".to_string(),
            data: None,
        })?;
    let payee = parse_address(payee_hex)?;

    let escrow_manager = node.escrow_manager().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Escrow manager not initialized".to_string(),
        data: None,
    })?;

    let escrows = escrow_manager.get_escrows_by_payee(&payee);
    Ok(serde_json::json!({
        "payee": payee_hex,
        "count": escrows.len(),
        "truncated": escrows.len() > LIST_RESPONSE_CAP,
        "escrows": escrows.iter().take(LIST_RESPONSE_CAP).map(escrow_to_json).collect::<Vec<_>>(),
    }))
}

// ---- Committee-DA possession challenges + availability (Task #92) -----------
//
// Validators audit each other's Red Stuff sliver custody: a challenge sends a
// fresh random nonce, the target answers with its full sliver plus a signature
// over the nonce-bound challenge message, and the challenger re-verifies the
// sliver against the blob commitment. Every resolution is persisted and folded
// into the target's rolling availability score.

fn require_da_committee(
    node: &Arc<TenzroNode>,
) -> std::result::Result<&Arc<crate::da_committee::DaCommitteeBackend>, JsonRpcError> {
    node.da_committee().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Committee-DA backend not initialized (validator role with consensus required)"
            .to_string(),
        data: None,
    })
}

fn parse_commitment(commitment_str: &str) -> std::result::Result<Hash, JsonRpcError> {
    let bare = commitment_str.strip_prefix("0x").unwrap_or(commitment_str);
    let bytes = hex::decode(bare).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid commitment hex: {}", e),
        data: None,
    })?;
    let arr: [u8; 32] = bytes.as_slice().try_into().map_err(|_| JsonRpcError {
        code: -32602,
        message: format!("Commitment must be 32 bytes, got {}", bytes.len()),
        data: None,
    })?;
    Ok(Hash::new(arr))
}

fn challenge_outcome_str(outcome: crate::da_committee::ChallengeOutcome) -> &'static str {
    match outcome {
        crate::da_committee::ChallengeOutcome::Passed => "passed",
        crate::da_committee::ChallengeOutcome::FailedNoResponse => "failed_no_response",
        crate::da_committee::ChallengeOutcome::FailedNotHeld => "failed_not_held",
        crate::da_committee::ChallengeOutcome::FailedBadProof => "failed_bad_proof",
    }
}

fn challenge_record_to_json(record: &crate::da_committee::ChallengeRecord) -> Value {
    serde_json::json!({
        "id": format!("0x{}", hex::encode(record.id.as_bytes())),
        "commitment": format!("0x{}", hex::encode(record.commitment.as_bytes())),
        "target_index": record.target_index,
        "target_address": format!("0x{}", hex::encode(record.target_address.as_bytes())),
        "nonce": format!("0x{}", hex::encode(record.nonce)),
        "issued_at_ms": record.issued_at_ms,
        "resolved_at_ms": record.resolved_at_ms,
        "outcome": challenge_outcome_str(record.outcome),
    })
}

fn availability_score_to_json(score: &crate::da_committee::AvailabilityScore) -> Value {
    serde_json::json!({
        "address": format!("0x{}", hex::encode(score.address.as_bytes())),
        "score": score.score,
        "max_score": crate::da_committee::AVAILABILITY_SCORE_MAX,
        "passes": score.passes,
        "failures": score.failures,
        "last_outcome": challenge_outcome_str(score.last_outcome),
        "last_challenge_ms": score.last_challenge_ms,
    })
}

/// `tenzro_daChallenge` — issue a possession challenge against committee member
/// `target_index` for `commitment`. Returns the resolved challenge record.
async fn handle_da_challenge(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let commitment_str = params
        .get("commitment")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing commitment".to_string(),
            data: None,
        })?;
    let commitment = parse_commitment(commitment_str)?;
    let target_index = params
        .get("target_index")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing target_index".to_string(),
            data: None,
        })? as usize;

    let backend = require_da_committee(node)?;
    let record = backend
        .challenge_possession(&commitment, target_index)
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Possession challenge failed to issue: {}", e),
            data: None,
        })?;
    Ok(challenge_record_to_json(&record))
}

/// `tenzro_daListChallenges` — resolved possession-challenge records, most
/// recently resolved first. Optional `limit` (default 100).
async fn handle_da_list_challenges(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let limit = params
        .as_ref()
        .and_then(|p| p.get("limit"))
        .and_then(|v| v.as_u64())
        .map(|l| l as usize)
        .unwrap_or(100)
        .min(LIST_RESPONSE_CAP);

    let backend = require_da_committee(node)?;
    let records = backend.custody_store().list_challenges(limit);
    Ok(serde_json::json!({
        "count": records.len(),
        "challenges": records.iter().map(challenge_record_to_json).collect::<Vec<_>>(),
    }))
}

/// `tenzro_daAvailability` — rolling availability scores. With an `address`
/// param, the single member's score (error if never challenged); without,
/// every scored member, lowest score first.
async fn handle_da_availability(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let backend = require_da_committee(node)?;
    let store = backend.custody_store();

    if let Some(addr_str) = params.as_ref().and_then(|p| p.get("address")).and_then(|v| v.as_str()) {
        let address = parse_address(addr_str)?;
        let score = store.get_availability(&address).ok_or_else(|| JsonRpcError {
            code: -32000,
            message: "No availability score for that address (never challenged)".to_string(),
            data: None,
        })?;
        return Ok(availability_score_to_json(&score));
    }

    let scores = store.list_availability();
    Ok(serde_json::json!({
        "count": scores.len(),
        "scores": scores.iter().map(availability_score_to_json).collect::<Vec<_>>(),
    }))
}

/// `tenzro_daCommittee` — the current DA committee snapshot: every member's
/// index and address, whether it is this node, and its availability score when
/// it has been challenged.
async fn handle_da_committee(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let backend = require_da_committee(node)?;
    let store = backend.custody_store();
    let local = backend.local_address();

    let members: Vec<Value> = backend
        .committee_members()
        .iter()
        .map(|m| {
            serde_json::json!({
                "index": m.index,
                "address": format!("0x{}", hex::encode(m.address.as_bytes())),
                "is_local": m.address == local,
                "availability": store.get_availability(&m.address).map(|s| availability_score_to_json(&s)),
            })
        })
        .collect();

    Ok(serde_json::json!({
        "local_address": format!("0x{}", hex::encode(local.as_bytes())),
        "count": members.len(),
        "members": members,
    }))
}

/// `tenzro_daListBlobs` — every blob commitment this node knows about: whether
/// it holds a sliver for it, and the availability certificate when this node
/// was the writer (attesting indices, quorum time, blob length).
async fn handle_da_list_blobs(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let backend = require_da_committee(node)?;
    let store = backend.custody_store();

    let blobs: Vec<Value> = store
        .known_commitments()
        .iter()
        .take(LIST_RESPONSE_CAP)
        .map(|commitment| {
            let sliver = store.get_sliver(commitment);
            let cert = store.get_cert(commitment);
            serde_json::json!({
                "commitment": format!("0x{}", hex::encode(commitment.as_bytes())),
                "held_sliver_index": sliver.as_ref().map(|s| s.sliver.node_index),
                "blob_len": sliver.as_ref().map(|s| s.blob_len)
                    .or_else(|| cert.as_ref().map(|c| c.blob_len)),
                "certificate": cert.as_ref().map(|c| serde_json::json!({
                    "attesting_indices": c.attestations.iter().map(|a| a.index).collect::<Vec<_>>(),
                    "quorum": c.shape.quorum(),
                    "certified_at_ms": c.certified_at_ms,
                    "root": format!("0x{}", hex::encode(c.root().as_bytes())),
                })),
            })
        })
        .collect();

    Ok(serde_json::json!({
        "count": blobs.len(),
        "blobs": blobs,
    }))
}

// ---- Prepaid streaming-service balances -------------------------------------
//
// A renter funds the streaming settlement path by locking on-chain TNZO into
// the prepaid ledger. The storage / compute runtimes stream per billing epoch
// out of this balance; the renter can withdraw any unspent balance back.

fn require_prepaid_ledger(
    node: &Arc<TenzroNode>,
) -> std::result::Result<&std::sync::Arc<tenzro_settlement::PrepaidLedger>, JsonRpcError> {
    node.prepaid_ledger().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Prepaid ledger not initialized (node lacks storage or token subsystem)"
            .to_string(),
        data: None,
    })
}

/// Reads the optional `asset` param, defaulting to TNZO (the only streamable
/// asset today).
fn prepaid_asset_param(params: &Value) -> tenzro_types::asset::AssetId {
    params
        .get("asset")
        .and_then(|v| v.as_str())
        .map(tenzro_types::asset::AssetId::new)
        .unwrap_or_else(tenzro_types::asset::AssetId::tnzo)
}

/// `tenzro_prepaidDeposit` — lock `amount` of the renter's on-chain TNZO into
/// the prepaid ledger. Returns the new prepaid balance.
async fn handle_prepaid_deposit(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let renter = parse_address_param(&params, "renter").ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing or invalid renter address".to_string(),
        data: None,
    })?;
    let amount = parse_u128_amount(&params, "amount").ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing or invalid amount".to_string(),
        data: None,
    })?;
    let asset = prepaid_asset_param(&params);
    let ledger = require_prepaid_ledger(node)?;

    let new_balance = ledger
        .deposit(renter, asset.clone(), amount)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Prepaid deposit failed: {}", e),
            data: None,
        })?;

    Ok(serde_json::json!({
        "renter": format!("0x{}", hex::encode(renter.as_bytes())),
        "asset": asset.as_str(),
        "deposited": amount.to_string(),
        "balance": new_balance.to_string(),
    }))
}

/// `tenzro_prepaidWithdraw` — return up to `amount` of the renter's unspent
/// prepaid balance to their on-chain account. Returns the amount withdrawn
/// (capped at the available prepaid balance) and the remaining balance.
async fn handle_prepaid_withdraw(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let renter = parse_address_param(&params, "renter").ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing or invalid renter address".to_string(),
        data: None,
    })?;
    let amount = parse_u128_amount(&params, "amount").ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing or invalid amount".to_string(),
        data: None,
    })?;
    let asset = prepaid_asset_param(&params);
    let ledger = require_prepaid_ledger(node)?;

    let withdrawn = ledger
        .withdraw(renter, asset.clone(), amount)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Prepaid withdraw failed: {}", e),
            data: None,
        })?;
    let balance = ledger.balance(&renter, &asset);

    Ok(serde_json::json!({
        "renter": format!("0x{}", hex::encode(renter.as_bytes())),
        "asset": asset.as_str(),
        "withdrawn": withdrawn.to_string(),
        "balance": balance.to_string(),
    }))
}

/// `tenzro_prepaidBalance` — read the renter's current prepaid balance.
async fn handle_prepaid_balance(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let renter = parse_address_param(&params, "renter").ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing or invalid renter address".to_string(),
        data: None,
    })?;
    let asset = prepaid_asset_param(&params);
    let ledger = require_prepaid_ledger(node)?;

    let balance = ledger.balance(&renter, &asset);

    Ok(serde_json::json!({
        "renter": format!("0x{}", hex::encode(renter.as_bytes())),
        "asset": asset.as_str(),
        "balance": balance.to_string(),
    }))
}

// ---- Agent memory tier (Phase B) RPCs ---------------------------------------
//
// `tenzro_memoryGrant`     — embed text via the configured TextEmbeddingRuntime
//                            and write the record to both Lance (vector kNN)
//                            and Tantivy (BM25 inverted index).
// `tenzro_memoryRecall`    — vector / text / hybrid (RRF k=60) search over an
//                            agent's own memory, scoped to a single agent_did.
// `tenzro_memoryArchive`   — push the canonical payload to the configured DA
//                            backend and rewrite the on-tier rows with
//                            `kind = Archived` + the resulting DaPointer.
// `tenzro_listMemoryRecords` — newest-first walk of an agent's memory for
//                            triage; reads from the text backend.

fn require_memory_manager(
    node: &Arc<TenzroNode>,
) -> std::result::Result<std::sync::Arc<tenzro_agent::memory::MemoryManager>, JsonRpcError> {
    let runtime = node.agent_runtime().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Agent runtime not initialized".to_string(),
        data: None,
    })?;
    runtime.memory_manager().cloned().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Memory manager not initialized".to_string(),
        data: None,
    })
}

/// Enforce that the authenticated bearer is allowed to read/write the
/// memory rows owned by `agent_did`. Allowed when:
///
///   - bearer DID exactly equals `agent_did` (the agent operates on
///     its own memory), or
///   - bearer is the controller_did of `agent_did` (delegated agent;
///     the controller can read its delegate's memory).
///
/// All other combinations — including unauthenticated requests and
/// requests where bearer is a stranger to `agent_did` — are rejected
/// with `-32001`. This closes the cross-DID memory exfiltration where
/// any caller could pass an arbitrary `agent_did` and read its rows.
async fn enforce_memory_access(
    node: &Arc<TenzroNode>,
    auth_ctx: &AuthContext,
    agent_did: &str,
) -> std::result::Result<(), JsonRpcError> {
    let outcome = resolve_auth_to_wallet(node, auth_ctx, None).await;
    let bearer_did = match outcome {
        AuthOutcome::Authenticated { bearer_did, .. } => bearer_did,
        AuthOutcome::AuthError(err) => return Err(err),
        AuthOutcome::Unauthenticated => {
            return Err(JsonRpcError {
                code: -32001,
                message: "Authentication required: agent memory access requires \
                          DPoP+JWT bearer auth so the server can bind the request \
                          to a specific DID. Unauthenticated reads would let any \
                          caller exfiltrate any agent's memory.".to_string(),
                data: None,
            });
        }
    };

    if bearer_did == agent_did {
        return Ok(());
    }

    // Delegated-agent path: bearer == controller_did(agent_did)?
    let registry = node.identity_registry().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "Identity registry not initialized".to_string(),
        data: None,
    })?;

    if let Ok(target) = registry.resolve(agent_did)
        && let Some(controller) = target.controller_did()
        && controller == bearer_did.as_str()
    {
        return Ok(());
    }

    Err(JsonRpcError {
        code: -32001,
        message: format!(
            "Bearer DID '{}' is not authorized to access memory of agent '{}'. \
             Memory access is restricted to the owning agent and its controller.",
            bearer_did, agent_did
        ),
        data: None,
    })
}

fn memory_record_to_json(r: &tenzro_agent::memory::MemoryRecord) -> Value {
    serde_json::json!({
        "id": r.id,
        "agent_did": r.agent_did,
        "created_at_ms": r.created_at_ms,
        "kind": r.kind.as_str(),
        "source": r.source.as_str(),
        "text": r.text,
        "metadata": r.metadata,
        "da_pointer": r.da_pointer,
        "has_embedding": r.embedding.is_some(),
    })
}

async fn handle_memory_grant(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
    auth_ctx: &AuthContext,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let agent_did = params
        .get("agent_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing agent_did".to_string(),
            data: None,
        })?
        .to_string();
    enforce_memory_access(node, auth_ctx, &agent_did).await?;
    let text = params
        .get("text")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing text".to_string(),
            data: None,
        })?
        .to_string();
    let kind_s = params
        .get("kind")
        .and_then(|v| v.as_str())
        .unwrap_or("granted");
    let source_s = params
        .get("source")
        .and_then(|v| v.as_str())
        .unwrap_or("controller");
    let kind = tenzro_agent::memory::MemoryKind::parse(kind_s).ok_or_else(|| JsonRpcError {
        code: -32602,
        message: format!("Invalid kind: {}", kind_s),
        data: None,
    })?;
    let source =
        tenzro_agent::memory::MemorySource::parse(source_s).ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("Invalid source: {}", source_s),
            data: None,
        })?;
    let metadata = params
        .get("metadata")
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    let mgr = require_memory_manager(node)?;
    let record = mgr
        .grant(agent_did, kind, source, text, metadata)
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("memory.grant: {}", e),
            data: None,
        })?;
    Ok(memory_record_to_json(&record))
}

async fn handle_memory_recall(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
    auth_ctx: &AuthContext,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let agent_did = params
        .get("agent_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing agent_did".to_string(),
            data: None,
        })?
        .to_string();
    enforce_memory_access(node, auth_ctx, &agent_did).await?;
    let query = params
        .get("query")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing query".to_string(),
            data: None,
        })?
        .to_string();
    let k = params
        .get("k")
        .and_then(|v| v.as_u64())
        .unwrap_or(10) as usize;
    let mode_s = params
        .get("mode")
        .and_then(|v| v.as_str())
        .unwrap_or("hybrid");
    let modes = match mode_s {
        "vector" => tenzro_agent::memory::SearchModes::VECTOR,
        "text" => tenzro_agent::memory::SearchModes::TEXT,
        "hybrid" => tenzro_agent::memory::SearchModes::HYBRID,
        other => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!("Invalid mode: {}", other),
                data: None,
            });
        }
    };
    let mgr = require_memory_manager(node)?;
    let hits = mgr
        .recall(agent_did, query, k, modes)
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("memory.recall: {}", e),
            data: None,
        })?;
    Ok(serde_json::json!({
        "count": hits.len(),
        "records": hits.iter().map(memory_record_to_json).collect::<Vec<_>>(),
    }))
}

async fn handle_memory_archive(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
    auth_ctx: &AuthContext,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let record_id = params
        .get("record_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing record_id".to_string(),
            data: None,
        })?
        .to_string();
    let agent_did = params
        .get("agent_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing agent_did".to_string(),
            data: None,
        })?
        .to_string();
    enforce_memory_access(node, auth_ctx, &agent_did).await?;
    let mgr = require_memory_manager(node)?;
    let archived = mgr
        .archive(&record_id, &agent_did)
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("memory.archive: {}", e),
            data: None,
        })?;
    Ok(memory_record_to_json(&archived))
}

async fn handle_list_memory_records(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
    auth_ctx: &AuthContext,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let agent_did = params
        .get("agent_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing agent_did".to_string(),
            data: None,
        })?
        .to_string();
    enforce_memory_access(node, auth_ctx, &agent_did).await?;
    let limit = (params
        .get("limit")
        .and_then(|v| v.as_u64())
        .unwrap_or(50) as usize)
        .min(LIST_RESPONSE_CAP);
    let mgr = require_memory_manager(node)?;
    let records = mgr.list(agent_did, limit).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("memory.list: {}", e),
        data: None,
    })?;
    Ok(serde_json::json!({
        "count": records.len(),
        "records": records.iter().map(memory_record_to_json).collect::<Vec<_>>(),
    }))
}

// ---- Iroh consumer surface (Phases A2 → D2) --------------------------------
//
// Exposes the shared `IrohBackedResolver` and the JSON-RPC-over-iroh ALPNs
// to RPC clients that want to use the QUIC + Pkarr + iroh-blobs substrate
// directly (without going through HTTPS). Internal subsystems
// (`IrohBlobsDaBackend`, `IrohGradientStore`, `IrohSealedShardStore`,
// memory-archive DA, A2A-over-iroh) consume the same resolver — see
// `crates/tenzro-iroh/src/lib.rs` rustdoc.
//
// The iroh data plane is always bound at startup. The only case in which
// `iroh_resolver` is `None` is when the initial bind failed (e.g. local
// UDP socket conflict, OS-level transport error). Clients receive `-32004`
// "iroh transport not bound" so the failure is distinguishable from a
// transient request-level error.

fn iroh_resolver_or_err(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Arc<tenzro_iroh::IrohBackedResolver>, JsonRpcError> {
    node.iroh_resolver.clone().ok_or_else(|| JsonRpcError {
        code: -32004,
        message: "iroh transport not bound on this node".to_string(),
        data: Some(serde_json::json!({
            "hint": "iroh failed to bind at startup; check node logs for the bind error"
        })),
    })
}

async fn handle_iroh_get_endpoint_id(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let resolver = iroh_resolver_or_err(node)?;
    let id = resolver.endpoint().id();
    // EndpointId Display = z-base-32 (n0 canonical); to_string() yields the
    // same form printed by `iroh node id`. Hex-encoded raw bytes are also
    // returned so callers that want the byte-identical TDIP key can use it.
    let id_str = id.to_string();
    let id_hex = hex::encode(id.as_bytes());
    Ok(serde_json::json!({
        "endpoint_id": id_str,
        "endpoint_id_hex": id_hex,
    }))
}

async fn handle_iroh_list_alpns(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let _ = iroh_resolver_or_err(node)?;
    // The shared router binds these ALPNs at bind time (see the resolver's
    // `bind_with_jsonrpc`): iroh-blobs (data plane) plus the JSON-RPC ALPNs
    // for A2A, MCP, MoE, and inference. All are registered whenever the
    // resolver is present — the JSON-RPC ones via bind-time trampolines that
    // main.rs later fills with the node-backed dispatchers.
    let mut alpns = vec![
        serde_json::json!({
            "alpn": "iroh-blobs",
            "description": "iroh-blobs BLAKE3 content-addressed transport",
        }),
    ];
    if node.iroh_a2a_dispatcher.is_some() {
        alpns.push(serde_json::json!({
            "alpn": String::from_utf8_lossy(tenzro_iroh::ALPN_A2A).to_string(),
            "description": "A2A JSON-RPC 2.0 over iroh (mirrors POST /a2a)",
        }));
    }
    if node.iroh_mcp_handler.is_some() {
        alpns.push(serde_json::json!({
            "alpn": String::from_utf8_lossy(tenzro_iroh::ALPN_MCP).to_string(),
            "description": "MCP JSON-RPC over iroh (mirrors the MCP server)",
        }));
    }
    alpns.push(serde_json::json!({
        "alpn": String::from_utf8_lossy(tenzro_iroh::ALPN_MOE).to_string(),
        "description": "Mixture-of-experts expert dispatch over iroh",
    }));
    if node.iroh_infer_dispatcher.is_some() {
        alpns.push(serde_json::json!({
            "alpn": String::from_utf8_lossy(tenzro_iroh::ALPN_INFER).to_string(),
            "description": "Inference JSON-RPC over iroh (mirrors tenzro_chat)",
        }));
    }
    Ok(serde_json::json!({ "alpns": alpns }))
}

async fn handle_iroh_get_info(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let resolver = iroh_resolver_or_err(node)?;
    let id = resolver.endpoint().id();
    let cfg = &node.config().iroh;
    let pkarr_relay = cfg.pkarr_relay_url.as_ref().map(|u| u.to_string());
    let mut alpns = vec!["iroh-blobs"];
    if node.iroh_a2a_dispatcher.is_some() {
        alpns.push("tenzro/a2a");
    }
    if node.iroh_mcp_handler.is_some() {
        alpns.push("tenzro/mcp");
    }
    alpns.push("tenzro/moe");
    if node.iroh_infer_dispatcher.is_some() {
        alpns.push("tenzro/infer");
    }
    Ok(serde_json::json!({
        "endpoint_id": id.to_string(),
        "endpoint_id_hex": hex::encode(id.as_bytes()),
        "pkarr_relay_url": pkarr_relay,
        "publish_to_n0_default_discovery": cfg.publish_to_n0_default_discovery,
        "docs_enabled": cfg.enable_docs,
        "bound_alpns": alpns,
    }))
}

async fn handle_iroh_publish_blob(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine as _;
    use tenzro_iroh::IrohResolver as _;
    let resolver = iroh_resolver_or_err(node)?;
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let bytes_b64 = params
        .get("bytes_b64")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing bytes_b64 (base64-encoded payload)".to_string(),
            data: None,
        })?;
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(bytes_b64)
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("bytes_b64 not valid base64: {e}"),
            data: None,
        })?;
    let size = bytes.len();
    let uri = resolver
        .publish_bytes(bytes::Bytes::from(bytes))
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("iroh publish_bytes: {e}"),
            data: None,
        })?;
    Ok(serde_json::json!({
        "tenzro_uri": uri.to_string(),
        "size_bytes": size,
    }))
}

async fn handle_iroh_fetch_blob(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine as _;
    use tenzro_iroh::IrohResolver as _;
    let resolver = iroh_resolver_or_err(node)?;
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let uri_str = params
        .get("tenzro_uri")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing tenzro_uri (e.g. tenzro://blob/<hash>)".to_string(),
            data: None,
        })?;
    let uri = tenzro_types::tenzro_uri::TenzroUri::parse(uri_str).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("parse tenzro_uri: {e}"),
        data: None,
    })?;
    let bytes = resolver
        .fetch_bytes(&uri)
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("iroh fetch_bytes: {e}"),
            data: None,
        })?;
    let b64 = base64::engine::general_purpose::STANDARD.encode(&bytes);
    Ok(serde_json::json!({
        "tenzro_uri": uri.to_string(),
        "size_bytes": bytes.len(),
        "bytes_b64": b64,
    }))
}

/// Generic dispatcher for any content-addressed `tenzro://` URI. Dispatches
/// `tenzro://memory/<did>/<uuid>` through [`MemoryManager`] (point-lookup; if
/// archived, follow the `DaPointer` to fetch the bulk payload from DA); falls
/// back to the iroh resolver's `fetch_blob` path for every other variant.
async fn handle_iroh_resolve_tenzro_uri(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine as _;
    let uri_str: String = {
        let params_ref = params.as_ref().ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing params".to_string(),
            data: None,
        })?;
        params_ref
            .get("tenzro_uri")
            .and_then(|v| v.as_str())
            .ok_or_else(|| JsonRpcError {
                code: -32602,
                message: "Missing tenzro_uri".to_string(),
                data: None,
            })?
            .to_string()
    };
    let uri = tenzro_types::tenzro_uri::TenzroUri::parse(&uri_str).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("parse tenzro_uri: {e}"),
        data: None,
    })?;

    if let tenzro_types::tenzro_uri::TenzroUri::Memory { agent_did, record_uuid } = &uri {
        let mgr = require_memory_manager(node)?;
        let record = mgr.get_by_id(agent_did, record_uuid).map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("memory get_by_id: {e}"),
            data: None,
        })?;
        let record = record.ok_or_else(|| JsonRpcError {
            code: -32004,
            message: format!("memory record {}/{} not found", agent_did, record_uuid),
            data: None,
        })?;
        // Archived records fan out to the DA backend; hot records serialize
        // the on-tier row as the canonical payload (same shape as what
        // `archive()` originally submitted).
        let bytes = if record.kind == tenzro_agent::memory::MemoryKind::Archived
            && record.da_pointer.is_some()
        {
            mgr.fetch_archived(&record).await.map_err(|e| JsonRpcError {
                code: -32000,
                message: format!("memory fetch_archived: {e}"),
                data: None,
            })?
        } else {
            serde_json::to_vec(&record).map_err(|e| JsonRpcError {
                code: -32603,
                message: format!("serialize memory record: {e}"),
                data: None,
            })?
        };
        let b64 = base64::engine::general_purpose::STANDARD.encode(&bytes);
        return Ok(serde_json::json!({
            "tenzro_uri": uri.to_string(),
            "size_bytes": bytes.len(),
            "bytes_b64": b64,
        }));
    }

    handle_iroh_fetch_blob(node, params).await
}

// ---- Workflow read RPCs (Canton-native workflow stack) ---------------------
//
// All workflow / obligation / approval / privacy-domain *writes* are handled
// by the privileged-VM workflow selectors (`0x01000040`–`0x0100004B`)
// dispatched via `tenzro_signAndSendTransaction`. The post-block scan in
// `EventLoop::process_workflow_logs` mirrors the emitted typed logs into
// the in-memory `WorkflowRuntime`. These RPCs read from that runtime, which
// is itself rehydrated from RocksDB (CF_SETTLEMENTS + CF_APPROVALS) on
// startup.

/// Parse a 32-byte Hash from a hex string (with or without `0x` prefix).
fn parse_workflow_hash_param(
    s: &str,
    field: &str,
) -> std::result::Result<tenzro_types::primitives::Hash, JsonRpcError> {
    let stripped = s.strip_prefix("0x").unwrap_or(s);
    let bytes = hex::decode(stripped).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid {} hex: {}", field, e),
        data: None,
    })?;
    tenzro_types::primitives::Hash::from_bytes(&bytes).ok_or_else(|| JsonRpcError {
        code: -32602,
        message: format!("{} must be 32 bytes", field),
        data: None,
    })
}

fn workflow_runtime_or_err(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Arc<crate::workflow_runtime::WorkflowRuntime>, JsonRpcError> {
    node.workflow_runtime()
        .cloned()
        .ok_or_else(|| JsonRpcError {
            code: -32000,
            message: "Workflow runtime not initialized".to_string(),
            data: None,
        })
}

fn workflow_status_from_str(
    s: &str,
) -> std::result::Result<tenzro_workflow::workflow::WorkflowStatus, JsonRpcError> {
    use tenzro_workflow::workflow::WorkflowStatus;
    Ok(match s {
        "draft" => WorkflowStatus::Draft,
        "awaiting_signatures" => WorkflowStatus::AwaitingSignatures,
        "active" => WorkflowStatus::Active,
        "suspended" => WorkflowStatus::Suspended,
        "settling" => WorkflowStatus::Settling,
        "completed" => WorkflowStatus::Completed,
        "failed" => WorkflowStatus::Failed,
        "disputed" => WorkflowStatus::Disputed,
        "cancelled" => WorkflowStatus::Cancelled,
        other => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!("Unknown workflow status: {}", other),
                data: None,
            });
        }
    })
}

fn ids_to_hex_array(ids: Vec<tenzro_types::primitives::Hash>) -> Vec<String> {
    ids.iter()
        .map(|h| format!("0x{}", hex::encode(h.as_bytes())))
        .collect()
}

/// `tenzro_getWorkflow` — fetch a workflow by id.
async fn handle_get_workflow(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let wf_id_hex = p.get("workflow_id").and_then(|v| v.as_str()).ok_or_else(|| {
        JsonRpcError {
            code: -32602,
            message: "Missing workflow_id".to_string(),
            data: None,
        }
    })?;
    let wf_id = parse_workflow_hash_param(wf_id_hex, "workflow_id")?;
    let rt = workflow_runtime_or_err(node)?;
    match rt.manager().get_workflow(&wf_id) {
        Some(wf) => serde_json::to_value(&wf).map_err(|e| JsonRpcError {
            code: -32603,
            message: format!("workflow serialize: {}", e),
            data: None,
        }),
        None => Ok(Value::Null),
    }
}

/// `tenzro_listWorkflowsByCreator` — list workflow ids created by a DID.
async fn handle_list_workflows_by_creator(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let creator = p
        .get("creator_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing creator_did".to_string(),
            data: None,
        })?;
    let rt = workflow_runtime_or_err(node)?;
    let mut ids = rt.manager().list_by_creator(creator);
    let total = ids.len();
    ids.truncate(LIST_RESPONSE_CAP);
    Ok(serde_json::json!({
        "creator_did": creator,
        "count": total,
        "truncated": total > LIST_RESPONSE_CAP,
        "workflow_ids": ids_to_hex_array(ids),
    }))
}

