/// `tenzro_videoEmbed`: produce a clip-level embedding from a video.
///
/// Params: `{ model_id, video_base64: String, normalize?: bool, frame_stride?: u32 }`
async fn handle_video_embed(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine;
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let b64 = p
        .get("video_base64")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("video_base64"))?;
    let normalize = p.get("normalize").and_then(|v| v.as_bool()).unwrap_or(false);
    let frame_stride = p
        .get("frame_stride")
        .and_then(|v| v.as_u64())
        .map(|n| n as u32);
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(b64)
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid base64 in 'video_base64': {}", e),
            data: None,
        })?;
    let cfg = VideoEmbedConfig {
        normalize,
        frame_stride,
    };
    let result = node
        .video_runtime
        .embed(model_id, bytes, cfg)
        .await
        .map_err(forecast_err)?;
    serde_json::to_value(result).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("video embed serialization: {}", e),
        data: None,
    })
}

/// Top-level dispatcher for `tenzro_chat`. Routes by shape:
///
/// - presence of `messages` → rich shape (multi-turn, tools, content blocks)
/// - presence of `message` → simple shape (single-turn string)
/// - both or neither → error
///
/// See `docs/chat-api.md` for the public contract.
pub(crate) async fn handle_chat(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.as_ref().ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let has_messages = p.get("messages").is_some();
    let has_message = p.get("message").is_some();
    match (has_messages, has_message) {
        (true, true) => Err(JsonRpcError {
            code: -32602,
            message: "Cannot specify both 'message' (simple) and 'messages' (rich) — pick one".to_string(),
            data: None,
        }),
        (true, false) => handle_chat_rich(node, params).await,
        (false, true) => handle_chat_simple(node, params).await,
        (false, false) => Err(JsonRpcError {
            code: -32602,
            message: "Missing 'message' (simple shape) or 'messages' (rich shape)".to_string(),
            data: None,
        }),
    }
}

/// Parses a [`RouteIntent`] from RPC params. Shared by `tenzro_routeIntent`
/// (discovery) and `tenzro_chatByIntent` (dispatch).
///
/// Fields: `use_case` (required, one of `chat`/`code`/`reasoning`/`summarize`/
/// `extract`/`embed`), `budget` (optional u128 per-request cap in smallest TNZO
/// unit; absent means no per-request cap), `optimize` (optional f32 in
/// `[0.0, 1.0]`, cost↔quality knob), `quality_floor` (optional `cheap`/
/// `strong`), `est_input_tokens` / `est_output_tokens` (optional u64 cost-
/// estimation inputs), `payer_did` (optional; enables the per-DID budget gate).
fn parse_route_intent(
    params: &Value,
) -> std::result::Result<tenzro_model::meta_router::RouteIntent, JsonRpcError> {
    use tenzro_model::meta_router::{Budget, QualityTier, RouteIntent, UseCase};

    let valid_use_cases = UseCase::ALL.join("|");
    let use_case_str = params
        .get("use_case")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("Missing 'use_case' ({valid_use_cases})"),
            data: None,
        })?;
    let use_case = UseCase::parse(use_case_str).ok_or_else(|| JsonRpcError {
        code: -32602,
        message: format!(
            "Unknown use_case '{use_case_str}' (expected one of {valid_use_cases})"
        ),
        data: None,
    })?;

    // Budget: accept a JSON number or decimal string (u128 exceeds JSON's safe
    // integer range), or absence → no per-request cap.
    let budget = match params.get("budget") {
        None | Some(Value::Null) => Budget::None,
        Some(v) => {
            let cap = if let Some(n) = v.as_u64() {
                n as u128
            } else if let Some(s) = v.as_str() {
                s.parse::<u128>().map_err(|_| JsonRpcError {
                    code: -32602,
                    message: format!("Invalid 'budget' value '{s}' (expected unsigned integer)"),
                    data: None,
                })?
            } else {
                return Err(JsonRpcError {
                    code: -32602,
                    message: "Invalid 'budget' (expected unsigned integer or decimal string)"
                        .to_string(),
                    data: None,
                });
            };
            Budget::PerRequestTnzo(cap)
        }
    };

    let mut intent = RouteIntent::new(use_case, budget);

    if let Some(o) = params.get("optimize").and_then(|v| v.as_f64()) {
        intent = intent.with_optimize(o as f32);
    }

    if let Some(floor_str) = params.get("quality_floor").and_then(|v| v.as_str()) {
        let floor = match floor_str.trim().to_lowercase().as_str() {
            "cheap" => QualityTier::Cheap,
            "strong" => QualityTier::Strong,
            other => {
                return Err(JsonRpcError {
                    code: -32602,
                    message: format!("Unknown quality_floor '{other}' (expected cheap|strong)"),
                    data: None,
                });
            }
        };
        intent = intent.with_quality_floor(floor);
    }

    let in_tok = params.get("est_input_tokens").and_then(|v| v.as_u64());
    let out_tok = params.get("est_output_tokens").and_then(|v| v.as_u64());
    if in_tok.is_some() || out_tok.is_some() {
        let cur_in = intent.est_input_tokens;
        let cur_out = intent.est_output_tokens;
        intent = intent.with_tokens(
            in_tok.unwrap_or(cur_in),
            out_tok.unwrap_or(cur_out),
        );
    }

    if let Some(did) = params.get("payer_did").and_then(|v| v.as_str()) {
        intent = intent.with_payer_did(did);
    }

    if let Some(addr_str) = params.get("payer_address").and_then(|v| v.as_str()) {
        intent = intent.with_payer_address(parse_address(addr_str)?);
    }

    Ok(intent)
}

/// Serializes a [`RouteDecision`] to the JSON-RPC result shape.
fn route_decision_to_json(d: &tenzro_model::meta_router::RouteDecision) -> Value {
    serde_json::json!({
        "model_id": d.model_id,
        "tier": format!("{:?}", d.tier).to_lowercase(),
        "estimated_cost": d.estimated_cost.to_string(),
        "fallback_chain": d.fallback_chain,
        "reason": d.reason,
    })
}

/// `tenzro_routeIntent` — runs the model-selection pipeline and returns the
/// chosen model, tier, estimated cost, fallback chain, and a selection trace.
/// Discovery only: no provider is dialed, no spend is recorded, and the per-DID
/// budget gate is still consulted (so an over-budget DID sees the rejection at
/// discovery time rather than at dispatch).
async fn handle_route_intent(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let intent = parse_route_intent(&params)?;

    let meta = node.meta_router().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "Meta-router not initialized on this node".to_string(),
        data: None,
    })?;

    match meta.route(&intent) {
        Ok(decision) => Ok(route_decision_to_json(&decision)),
        Err(tenzro_model::ModelError::NoProvidersAvailable(m)) => Err(JsonRpcError {
            code: -32004,
            message: m,
            data: None,
        }),
        Err(e) => Err(JsonRpcError {
            code: -32000,
            message: e.to_string(),
            data: None,
        }),
    }
}

/// `tenzro_chatByIntent` — resolves an intent to a model, then dispatches the
/// chat through the same path as a named-model request. The resolved `model_id`
/// is injected into the params and `tenzro_chat` handles provider selection,
/// provenance, and usage recording. The `RouteDecision` is attached to the
/// response under `route` for observability.
///
/// Params are the union of `parse_route_intent`'s intent fields and
/// `tenzro_chat`'s chat fields (`message` for the simple shape or `messages`
/// for the rich shape). A `model_id` in the params is overwritten by the
/// resolved model.
async fn handle_chat_by_intent(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let mut params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let intent = parse_route_intent(&params)?;

    let decision = {
        let meta = node.meta_router().ok_or_else(|| JsonRpcError {
            code: -32603,
            message: "Meta-router not initialized on this node".to_string(),
            data: None,
        })?;
        match meta.route(&intent) {
            Ok(d) => d,
            Err(tenzro_model::ModelError::NoProvidersAvailable(m)) => {
                return Err(JsonRpcError { code: -32004, message: m, data: None });
            }
            Err(e) => {
                return Err(JsonRpcError { code: -32000, message: e.to_string(), data: None });
            }
        }
    };

    // Inject the resolved model into the chat params, dropping any caller-
    // supplied model so intent routing is authoritative.
    if let Value::Object(ref mut map) = params {
        map.insert("model_id".to_string(), Value::String(decision.model_id.clone()));
        map.remove("model");
    }

    let mut result = handle_chat(node, Some(params)).await?;
    if let Value::Object(ref mut map) = result {
        map.insert("route".to_string(), route_decision_to_json(&decision));
    }
    Ok(result)
}

/// `tenzro_orchestrate` — the intent→capabilities runtime. Plans an ordered set
/// of capability steps (model / skill / tool / agent / swarm) for a natural-
/// language `intent`, cost-checks the plan against the payer's wallet ceiling,
/// and executes it front-to-back through the same handlers a direct call would
/// take (so provenance, usage recording, and commission settlement stay
/// identical). One layer above `tenzro_chatByIntent`: that resolves a single
/// model; this composes models with the skill/tool registries and the swarm
/// runtime.
///
/// Params: `intent` (required, the natural-language goal), plus the intent
/// fields shared with `tenzro_routeIntent` (`use_case`, `budget`, `payer_did`,
/// `payer_address`) and `max_iterations` (re-plan bound, clamped `[1, 6]`).
async fn handle_orchestrate(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use crate::orchestrator::OrchestratorError;
    use tenzro_model::meta_router::{Budget, UseCase};

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let intent_text = params
        .get("intent")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'intent' (natural-language goal)".to_string(),
            data: None,
        })?;

    let mut request = crate::orchestrator::OrchestrationRequest::new(intent_text);

    // Use case: optional; defaults to Chat. Reuses the same parse contract as
    // the intent-routing RPCs.
    if let Some(uc_str) = params.get("use_case").and_then(|v| v.as_str()) {
        let use_case = UseCase::parse(uc_str).ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!(
                "Unknown use_case '{uc_str}' (expected one of {})",
                UseCase::ALL.join("|")
            ),
            data: None,
        })?;
        request = request.with_use_case(use_case);
    }

    // Budget: JSON number or decimal string (u128 exceeds JSON's safe integer
    // range), or absence => no per-request cap.
    match params.get("budget") {
        None | Some(Value::Null) => {}
        Some(v) => {
            let cap = if let Some(n) = v.as_u64() {
                n as u128
            } else if let Some(s) = v.as_str() {
                s.parse::<u128>().map_err(|_| JsonRpcError {
                    code: -32602,
                    message: format!("Invalid 'budget' value '{s}' (expected unsigned integer)"),
                    data: None,
                })?
            } else {
                return Err(JsonRpcError {
                    code: -32602,
                    message: "Invalid 'budget' (expected unsigned integer or decimal string)"
                        .to_string(),
                    data: None,
                });
            };
            request = request.with_budget(Budget::PerRequestTnzo(cap));
        }
    }

    if let Some(did) = params.get("payer_did").and_then(|v| v.as_str()) {
        request = request.with_payer_did(did);
    }
    if let Some(addr_str) = params.get("payer_address").and_then(|v| v.as_str()) {
        request = request.with_payer_address(parse_address(addr_str)?);
    }
    if let Some(n) = params.get("max_iterations").and_then(|v| v.as_u64()) {
        request = request.with_max_iterations(n as u32);
    }

    let catalog = crate::orchestrator_bridge::build_catalog_snapshot(node);
    let orchestrator = crate::orchestrator_bridge::build_orchestrator(node.clone());

    match orchestrator.execute(&request, &catalog).await {
        Ok(outcome) => {
            let steps: Vec<Value> = outcome
                .steps
                .iter()
                .map(|s| {
                    serde_json::json!({
                        "kind": s.kind,
                        "output": s.output,
                        "detail": s.detail,
                    })
                })
                .collect();
            Ok(serde_json::json!({
                "plan": outcome.plan,
                "steps": steps,
                // u128 stringified — exceeds JSON's safe integer range.
                "estimated_cost": outcome.estimated_cost.to_string(),
                "iterations": outcome.iterations,
            }))
        }
        Err(OrchestratorError::OverBudget { estimated, balance }) => Err(JsonRpcError {
            code: -32004,
            message: format!(
                "plan exceeds wallet ceiling: estimated {estimated} > balance {balance}"
            ),
            data: Some(serde_json::json!({
                "estimated": estimated.to_string(),
                "balance": balance.to_string(),
            })),
        }),
        Err(e @ OrchestratorError::NoCapability(_)) => Err(JsonRpcError {
            code: -32004,
            message: e.to_string(),
            data: None,
        }),
        Err(e @ OrchestratorError::Unavailable(_)) => Err(JsonRpcError {
            code: -32603,
            message: e.to_string(),
            data: None,
        }),
        Err(e @ OrchestratorError::InvalidPlan(_)) => Err(JsonRpcError {
            code: -32602,
            message: e.to_string(),
            data: None,
        }),
        Err(e) => Err(JsonRpcError {
            code: -32000,
            message: e.to_string(),
            data: None,
        }),
    }
}

/// Announcement pubkey pinned at gossip time for a network-served model
/// (first-seen TOFU pinning in the `ModelAnnouncement` consumer). `None`
/// when the model was not discovered via gossip or the provider announced
/// without a key — unsigned providers stay fully routable, and any manifest
/// they attach is then verified against its embedded key only.
fn pinned_announcement_pubkey(
    node: &Arc<TenzroNode>,
    model_id: &str,
    provider: &str,
) -> Option<Vec<u8>> {
    node.network_models_snapshot()
        .into_iter()
        .find(|e| e.registration.model_id == model_id && e.registration.provider == provider)
        .map(|e| e.registration.pubkey)
        .filter(|pk| !pk.is_empty())
}

/// Verify a `tenzro_provenance` manifest attached to a forwarded inference
/// response: content hash over the output bytes, model-id binding,
/// registered-key binding when an announcement pubkey is pinned, and the
/// manifest signature. Returns the manifest when it verifies; logs and
/// returns `None` otherwise so optional-verification callers can pass the
/// response through unsigned.
fn verify_forwarded_provenance(
    value: Option<&Value>,
    output: &[u8],
    model_id: &str,
    registered_pubkey: Option<&[u8]>,
    provider_label: &str,
) -> Option<tenzro_types::ProvenanceManifest> {
    let value = value.filter(|v| !v.is_null())?;
    match serde_json::from_value::<tenzro_types::ProvenanceManifest>(value.clone()) {
        Ok(manifest) => match tenzro_model::verify_response_manifest(
            &manifest,
            output,
            model_id,
            registered_pubkey,
        ) {
            Ok(()) => Some(manifest),
            Err(e) => {
                tracing::warn!(provider = %provider_label, model = %model_id,
                    "Provider attached an invalid provenance manifest: {}", e);
                None
            }
        },
        Err(e) => {
            tracing::warn!(provider = %provider_label, model = %model_id,
                "Provider attached a malformed provenance manifest: {}", e);
            None
        }
    }
}

/// Sign a locally-generated inference output with the node's provenance
/// signer (the long-term Ed25519 announce key) and cache the manifest in
/// the provenance store. `None` when the node has no signer — serving
/// unsigned stays fully supported.
/// Hex identity of this node as an inference provider — derived from the
/// announce signer's public key, matching the provider string carried on
/// signed model announcements.
fn local_provider_hex(node: &Arc<TenzroNode>) -> String {
    node.announce_signer()
        .map(|s| format!("0x{}", hex::encode(s.public_key().as_bytes())))
        .unwrap_or_else(|| "unknown".to_string())
}

/// Persist a TOPLOC commitment produced by the local runtime and build the
/// `commitment` object returned on chat/inference responses. Returns `None`
/// when the result carries no commitment (external engine, speculative
/// decoding, or `verifiable` not requested) or when the node has no durable
/// storage — callers degrade to an unverifiable response rather than fail.
fn store_local_commitment(
    node: &Arc<TenzroNode>,
    model_id: &str,
    commitment: Option<&tenzro_model::InferenceCommitment>,
) -> Option<Value> {
    let commitment = commitment?;
    let manager = node.challenge_manager()?;
    let provider = local_provider_hex(node);
    match manager.store_commitment(model_id, &provider, commitment) {
        Ok(hash) => Some(serde_json::json!({
            "hash": hash,
            "k": commitment.k,
            "steps": commitment.steps.len(),
        })),
        Err(e) => {
            tracing::warn!(model = %model_id,
                "Failed to persist inference commitment: {}", e);
            None
        }
    }
}

/// Shared lookup for the challenge-lifecycle handlers — errors when the
/// node has no durable storage (commitments cannot survive restarts, so
/// the whole surface is disabled rather than silently lossy).
fn challenge_manager_or_err(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Arc<crate::inference_challenge::ChallengeManager>, JsonRpcError> {
    node.challenge_manager().cloned().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Verifiable inference is unavailable: node has no durable storage".to_string(),
        data: None,
    })
}

fn challenge_to_json(c: &crate::inference_challenge::InferenceChallenge) -> Value {
    serde_json::to_value(c).unwrap_or(Value::Null)
}

/// `tenzro_getInferenceCommitment` — fetch a stored TOPLOC commitment by
/// its canonical hash. Returns the serving context plus the full top-k
/// logit blob so an external verifier holding the weights can re-execute.
async fn handle_get_inference_commitment(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let hash = params
        .get("commitment_hash")
        .and_then(|v| v.as_str())
        .map(|s| s.trim_start_matches("0x"))
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing commitment_hash".to_string(),
            data: None,
        })?;
    let manager = challenge_manager_or_err(node)?;
    let stored = manager.get_commitment(hash).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Commitment lookup failed: {e}"),
        data: None,
    })?;
    match stored {
        Some(s) => Ok(serde_json::json!({
            "commitment_hash": hash,
            "model_id": s.model_id,
            "provider": s.provider,
            "created_at": s.created_at,
            "k": s.commitment.k,
            "prompt_tokens": s.commitment.prompt_tokens,
            "steps": s.commitment.steps.len(),
            "commitment": s.commitment,
        })),
        None => Ok(Value::Null),
    }
}

/// `tenzro_verifyInferenceCommitment` — re-execute a committed inference
/// as a single prefill on this node and fuzzy-compare the recomputed
/// logits against the commitment (TOPLOC check). The caller supplies the
/// original prompt — it is never stored. Requires the model loaded
/// locally in serial mode with the same weights the provider used.
async fn handle_verify_inference_commitment(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let hash = params
        .get("commitment_hash")
        .and_then(|v| v.as_str())
        .map(|s| s.trim_start_matches("0x"))
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing commitment_hash".to_string(),
            data: None,
        })?;
    let prompt = params
        .get("prompt")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing prompt (the verifier supplies the original prompt)".to_string(),
            data: None,
        })?;
    let manager = challenge_manager_or_err(node)?;
    let stored = manager
        .get_commitment(hash)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Commitment lookup failed: {e}"),
            data: None,
        })?
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("No stored commitment with hash {hash}"),
            data: None,
        })?;
    let runtime = node.model_runtime.as_ref().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Model runtime not initialized".to_string(),
        data: None,
    })?;
    let outcome = runtime
        .verify_inference_commitment(&stored.model_id, prompt, stored.commitment)
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Verification failed: {e}"),
            data: None,
        })?;
    Ok(serde_json::json!({
        "commitment_hash": hash,
        "model_id": stored.model_id,
        "provider": stored.provider,
        "pass": outcome.pass,
        "steps_total": outcome.steps_total,
        "steps_passed": outcome.steps_passed,
        "failing_steps": outcome.failing_steps,
    }))
}

/// `tenzro_fileInferenceChallenge` — open a dispute against a stored
/// commitment. Model and provider are read from the stored envelope so a
/// filing cannot misattribute. Resolution is a separate, operator-gated
/// step.
async fn handle_file_inference_challenge(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let hash = params
        .get("commitment_hash")
        .and_then(|v| v.as_str())
        .map(|s| s.trim_start_matches("0x"))
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing commitment_hash".to_string(),
            data: None,
        })?;
    let challenger = params
        .get("challenger")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing challenger (address or DID)".to_string(),
            data: None,
        })?;
    let reason = params
        .get("reason")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let manager = challenge_manager_or_err(node)?;
    let challenge = manager
        .file(hash, challenger, reason)
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("Challenge filing rejected: {e}"),
            data: None,
        })?;
    Ok(challenge_to_json(&challenge))
}

/// `tenzro_getInferenceChallenge` — look up one challenge by id.
async fn handle_get_inference_challenge(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let id = params
        .get("challenge_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing challenge_id".to_string(),
            data: None,
        })?;
    let manager = challenge_manager_or_err(node)?;
    Ok(manager
        .get(id)
        .map(|c| challenge_to_json(&c))
        .unwrap_or(Value::Null))
}

/// `tenzro_listInferenceChallenges` — list challenges, optionally
/// filtered by `status` (filed | upheld | dismissed) and/or `provider`.
async fn handle_list_inference_challenges(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let status = params
        .as_ref()
        .and_then(|p| p.get("status"))
        .and_then(|v| v.as_str())
        .map(|s| {
            crate::inference_challenge::ChallengeStatus::parse(s).ok_or_else(|| JsonRpcError {
                code: -32602,
                message: format!("Unknown status '{s}' (expected filed | upheld | dismissed)"),
                data: None,
            })
        })
        .transpose()?;
    let provider = params
        .as_ref()
        .and_then(|p| p.get("provider"))
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());
    let manager = challenge_manager_or_err(node)?;
    let challenges = manager.list(status, provider.as_deref());
    Ok(serde_json::json!({
        "count": challenges.len(),
        "challenges": challenges.iter().map(challenge_to_json).collect::<Vec<_>>(),
    }))
}

/// `tenzro_resolveInferenceChallenge` — operator verdict on a filed
/// challenge (admin-token-gated via `requires_admin_token`). When the
/// resolver has the weights loaded locally and the caller supplies the
/// original `prompt`, the node re-runs the TOPLOC check itself and the
/// verdict follows the outcome; otherwise the caller passes an explicit
/// `upheld` boolean (e.g. after running `tenzro_verifyInferenceCommitment`
/// on a node that holds the weights).
///
/// An upheld challenge fires the existing provider penalty paths — the
/// `ProviderManager` call-failure reputation decrement and
/// `ComputeBondManager::record_failure` — rather than a new slashing
/// mechanism. Both are best-effort: a provider unknown to this node's
/// registries still gets the on-record upheld verdict.
async fn handle_resolve_inference_challenge(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let id = params
        .get("challenge_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing challenge_id".to_string(),
            data: None,
        })?;
    let manager = challenge_manager_or_err(node)?;
    let filed = manager.get(id).ok_or_else(|| JsonRpcError {
        code: -32602,
        message: format!("Unknown challenge {id}"),
        data: None,
    })?;

    // Verdict: local re-execution when a prompt is supplied and the
    // weights are loaded here; explicit `upheld` boolean otherwise.
    let (upheld, verification) = if let Some(prompt) =
        params.get("prompt").and_then(|v| v.as_str())
    {
        let stored = manager
            .get_commitment(&filed.commitment_hash)
            .map_err(|e| JsonRpcError {
                code: -32000,
                message: format!("Commitment lookup failed: {e}"),
                data: None,
            })?
            .ok_or_else(|| JsonRpcError {
                code: -32000,
                message: "Challenge references a missing commitment".to_string(),
                data: None,
            })?;
        let runtime = node.model_runtime.as_ref().ok_or_else(|| JsonRpcError {
            code: -32000,
            message: "Model runtime not initialized".to_string(),
            data: None,
        })?;
        let outcome = runtime
            .verify_inference_commitment(&stored.model_id, prompt, stored.commitment)
            .await
            .map_err(|e| JsonRpcError {
                code: -32000,
                message: format!("Verification failed: {e}"),
                data: None,
            })?;
        let verification = serde_json::json!({
            "pass": outcome.pass,
            "steps_total": outcome.steps_total,
            "steps_passed": outcome.steps_passed,
            "failing_steps": outcome.failing_steps,
        });
        // A failing verification upholds the challenge.
        (!outcome.pass, Some(verification))
    } else {
        let upheld = params
            .get("upheld")
            .and_then(|v| v.as_bool())
            .ok_or_else(|| JsonRpcError {
                code: -32602,
                message: "Provide either prompt (local re-execution) or upheld (explicit verdict)"
                    .to_string(),
                data: None,
            })?;
        (upheld, params.get("verification").cloned())
    };

    let resolved = manager
        .resolve(id, upheld, verification)
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("Resolution rejected: {e}"),
            data: None,
        })?;

    let mut reputation_penalized = false;
    let mut bond_failure_recorded = false;
    if upheld {
        // Reputation: the stored provider string is the announce-signer
        // pubkey hex, which is also the provider's registry address.
        if let Ok(addr) =
            tenzro_types::primitives::Address::from_hex(resolved.provider.trim_start_matches("0x"))
        {
            if let Some(pm) = node.provider_manager() {
                pm.record_call_failure(&addr);
                reputation_penalized = true;
            }
            // Compute bond: bonds are keyed by DID; match on the bond's
            // registered provider address. An explicit `provider_did`
            // param short-circuits the scan.
            if let Some(bonds) = node.compute_bond_manager() {
                let did = params
                    .get("provider_did")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string())
                    .or_else(|| {
                        bonds
                            .list()
                            .into_iter()
                            .find(|b| b.provider_address == addr)
                            .map(|b| b.provider_did)
                    });
                if let Some(did) = did {
                    match bonds.record_failure(&did) {
                        Ok(count) => {
                            bond_failure_recorded = true;
                            tracing::info!(
                                challenge = %id,
                                provider = %resolved.provider,
                                did = %did,
                                failure_count = count,
                                "Inference challenge upheld — compute-bond failure recorded"
                            );
                        }
                        Err(e) => tracing::warn!(
                            challenge = %id,
                            did = %did,
                            "Compute-bond failure record failed: {e}"
                        ),
                    }
                }
            }
        } else {
            tracing::warn!(
                challenge = %id,
                provider = %resolved.provider,
                "Upheld challenge provider string is not a parseable address; \
                 penalty paths skipped"
            );
        }
    }

    let mut out = challenge_to_json(&resolved);
    if let Some(obj) = out.as_object_mut() {
        obj.insert("reputation_penalized".to_string(), Value::Bool(reputation_penalized));
        obj.insert("bond_failure_recorded".to_string(), Value::Bool(bond_failure_recorded));
    }
    Ok(out)
}

fn sign_local_response(
    node: &Arc<TenzroNode>,
    model_id: &str,
    output: &[u8],
) -> Option<tenzro_types::ProvenanceManifest> {
    let signer = node.provenance_signer()?;
    let provider_addr = node
        .announce_signer()
        .map(|s| {
            let pk = s.public_key();
            let bytes = pk.as_bytes();
            let mut buf = [0u8; 32];
            let len = bytes.len().min(32);
            buf[32 - len..].copy_from_slice(&bytes[..len]);
            Address(buf)
        })
        .unwrap_or_default();
    match signer.sign(
        model_id,
        provider_addr,
        output,
        tenzro_model::ASSERTION_AI_GENERATED,
    ) {
        Ok(manifest) => {
            if let Some(store) = node.provenance_store() {
                store.put(manifest.clone());
            }
            Some(manifest)
        }
        Err(e) => {
            tracing::warn!(model = %model_id,
                "Failed to sign provenance manifest for local response: {}", e);
            None
        }
    }
}

/// Forward a `tenzro_chat` JSON-RPC frame to a network model provider.
///
/// Peer-identity path first: when the provider advertised an iroh
/// `EndpointId`, dial it on the `tenzro/infer` ALPN (Pkarr-resolved,
/// NAT-agnostic). This is the only path that reaches a provider whose
/// `rpc_endpoint` is a loopback address — which is every non-RPC-public
/// and every NATed node. HTTP is the fallback, tried only when there is no
/// iroh id or the iroh dial fails at the transport layer, and it is bounded
/// by a short connect timeout so a wrong/unreachable address fails fast
/// instead of hanging the caller.
/// Resolve the iroh `EndpointId` a network provider advertised for `model_id`,
/// skipping this node's own announcement so we never self-dial. Returns `None`
/// when no peer advertises the model with a non-empty iroh endpoint id (the
/// caller then falls back to the announced HTTP `rpc_endpoint`).
fn network_provider_iroh_endpoint(node: &Arc<TenzroNode>, model_id: &str) -> Option<String> {
    let own = node
        .iroh_resolver
        .as_ref()
        .map(|r| r.endpoint_id().to_string());
    for entry in node.network_models_snapshot() {
        let reg = &entry.registration;
        if reg.model_id != model_id || reg.iroh_endpoint_id.is_empty() {
            continue;
        }
        if own.as_deref() == Some(reg.iroh_endpoint_id.as_str()) {
            continue;
        }
        return Some(reg.iroh_endpoint_id.clone());
    }
    None
}

async fn forward_network_chat(
    node: &Arc<TenzroNode>,
    iroh_endpoint_id: Option<&str>,
    http_endpoint: &str,
    provider_name: &str,
    forward_body: &Value,
) -> std::result::Result<Value, JsonRpcError> {
    // iroh first.
    if let (Some(endpoint_id_str), Some(resolver)) = (iroh_endpoint_id, node.iroh_resolver.as_ref())
    {
        match endpoint_id_str.parse::<tenzro_iroh::EndpointId>() {
            Ok(endpoint_id) => {
                let frame = bytes::Bytes::from(serde_json::to_vec(forward_body).map_err(|e| {
                    JsonRpcError {
                        code: -32603,
                        message: format!("encode infer frame: {e}"),
                        data: None,
                    }
                })?);
                match tenzro_iroh::jsonrpc_call(
                    resolver.endpoint(),
                    endpoint_id,
                    tenzro_iroh::ALPN_INFER,
                    frame,
                )
                .await
                {
                    Ok(resp_bytes) => {
                        return serde_json::from_slice(&resp_bytes).map_err(|e| JsonRpcError {
                            code: -32000,
                            message: format!("parse provider infer response: {e}"),
                            data: None,
                        });
                    }
                    Err(e) => {
                        // Transport-level failure only — fall through to HTTP.
                        tracing::debug!(
                            provider = %provider_name,
                            "infer iroh dispatch failed, falling back to http: {e}"
                        );
                    }
                }
            }
            Err(e) => {
                tracing::warn!(
                    provider = %provider_name,
                    endpoint_id = endpoint_id_str,
                    "provider advertised unparseable iroh endpoint id: {e}"
                );
            }
        }
    }

    // HTTP fallback. A loopback `rpc_endpoint` will refuse the connection
    // fast; a wrong public address is bounded by the connect timeout rather
    // than the (long) total-request timeout, so the caller is never pinned
    // for two minutes on an unreachable peer.
    let client = reqwest::Client::builder()
        .connect_timeout(std::time::Duration::from_secs(5))
        .timeout(std::time::Duration::from_secs(60))
        .build()
        .unwrap_or_else(|_| reqwest::Client::new());

    let resp = client
        .post(http_endpoint)
        .json(forward_body)
        .send()
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Failed to reach provider {provider_name} at {http_endpoint}: {e}"),
            data: None,
        })?;

    resp.json().await.map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Failed to parse provider response: {e}"),
        data: None,
    })
}

async fn handle_chat_simple(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    // Accept both `model_id` (Tenzro RPC-style, canonical) and `model`
    // (OpenAI/MCP-style). Either key is valid in the JSON payload.
    let model_query = params
        .get("model_id")
        .or_else(|| params.get("model"))
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'model_id' (or 'model') parameter".to_string(),
            data: None,
        })?;

    let message = params
        .get("message")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'message' parameter".to_string(),
            data: None,
        })?;

    // Bound the message so a single request cannot pin a provider's context.
    tenzro_types::validation::validate_string_len(
        message, "message", tenzro_types::validation::MAX_CHAT_MESSAGE_LEN,
    ).map_err(|e| JsonRpcError { code: -32602, message: e.to_string(), data: None })?;

    // Opt-in verified-response mode: when set, the response must carry a
    // provenance manifest that verifies against the provider's registered
    // signing key. Default off — unsigned providers remain fully routable.
    let require_signed = params
        .get("require_signed")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    // Opt-in verifiable-inference mode (TOPLOC scheme): when set, the
    // serving runtime commits to the top-k raw logits of every generated
    // token. The commitment is stored content-addressed in CF_CHALLENGES
    // and its hash returned on the response, so the caller — who holds
    // the prompt — can later dispute the result via
    // `tenzro_fileInferenceChallenge` and any peer with the same weights
    // can re-execute the check as a single prefill. Default off; models
    // served through external engines return no commitment regardless.
    let verifiable = params
        .get("verifiable")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    // Resolve model: try service registry, then local served_models, then
    // gossip-discovered network models. This ensures non-provider nodes (e.g.
    // the public RPC tier) can forward chat requests to any validator that
    // has advertised itself via `tenzro/models`.
    let mut service = node.get_model_service(model_query)
        .or_else(|| node.find_model_service_by_model_id(model_query));

    // Sibling to `service` for network-resolved models: the provider's iroh
    // `EndpointId` (hex) carried in the signed announcement. Threaded here
    // because `ModelServiceInstance` has no iroh field — the network branch
    // dials this identity over the `tenzro/infer` ALPN before falling back to
    // the loopback-only `api_endpoint`.
    let mut net_iroh_endpoint_id: Option<String> = None;

    if service.is_none() && !node.served_models.contains_key(model_query) {
        // Identity of this node's own iroh endpoint, if bound — used to skip
        // any announcement that resolves back to us (self-dial guard).
        let own_endpoint_id = node
            .iroh_resolver
            .as_ref()
            .map(|r| r.endpoint_id().to_string());

        for entry in node.network_models_snapshot() {
            let reg = &entry.registration;
            if reg.model_id == model_query {
                // Self-dial guard: never treat our own announcement as a
                // remote provider. A node that both serves and consumes would
                // otherwise dial its own loopback endpoint and hang.
                let is_self = own_endpoint_id
                    .as_deref()
                    .is_some_and(|own| !reg.iroh_endpoint_id.is_empty()
                        && reg.iroh_endpoint_id == own);
                if is_self {
                    continue;
                }
                net_iroh_endpoint_id = if reg.iroh_endpoint_id.is_empty() {
                    None
                } else {
                    Some(reg.iroh_endpoint_id.clone())
                };
                service = Some(tenzro_types::model::ModelServiceInstance {
                    instance_id: format!("net-{}-{}", reg.model_id, reg.provider),
                    model_id: reg.model_id.clone(),
                    model_name: reg.name.clone(),
                    provider_address: tenzro_types::primitives::Address::from_hex(&reg.provider).unwrap_or_default(),
                    provider_name: reg.provider.clone(),
                    location: tenzro_types::model::ModelLocation::Network,
                    api_endpoint: reg.rpc_endpoint.clone(),
                    mcp_endpoint: String::new(),
                    status: tenzro_types::model::ServiceStatus::Online,
                    parameters: reg.parameters.clone(),
                    pricing: tenzro_types::model::PricingConfig {
                        price_per_input_token: reg.pricing.per_token.unwrap_or(0),
                        price_per_output_token: reg.pricing.per_token.unwrap_or(0),
                        minimum_price: reg.pricing.per_request,
                        pricing_model: tenzro_types::model::PricingModel::PerToken,
                    },
                    created_at: 0,
                    last_seen: std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_secs(),
                    load_info: None,
                    iroh_endpoint_id: reg.iroh_endpoint_id.clone(),
                });
                break;
            }
        }
    }

    let is_local = if let Some(ref svc) = service {
        svc.location == ModelLocation::Local
    } else {
        node.served_models.contains_key(model_query)
    };

    let model_id = if let Some(ref svc) = service {
        svc.model_id.clone()
    } else {
        model_query.to_string()
    };

    // Parse optional generation config
    let temperature = params.get("temperature").and_then(|v| v.as_f64()).unwrap_or(0.7);
    tenzro_types::validation::validate_temperature(temperature)
        .map_err(|e| JsonRpcError { code: -32602, message: e.to_string(), data: None })?;

    let max_tokens = params.get("max_tokens").and_then(|v| v.as_u64()).unwrap_or(512);
    tenzro_types::validation::validate_numeric_bound(
        max_tokens, "max_tokens", tenzro_types::validation::MAX_INFERENCE_TOKENS,
    ).map_err(|e| JsonRpcError { code: -32602, message: e.to_string(), data: None })?;

    let config = GenerationConfig {
        temperature,
        top_p: params.get("top_p").and_then(|v| v.as_f64()).unwrap_or(0.9),
        max_tokens: max_tokens as u32,
        repeat_penalty: params.get("repeat_penalty").and_then(|v| v.as_f64()).unwrap_or(1.1) as f32,
        // Optional Multi-Token-Prediction draft count (1..=6). When set
        // and the target's catalog entry pairs a drafter, the runtime
        // attempts speculative decoding; otherwise returns a structured
        // `MtpUnavailable` error.
        draft_n: params
            .get("draft_n")
            .and_then(|v| v.as_u64())
            .and_then(|n| u8::try_from(n).ok())
            .filter(|n| (1..=6).contains(n)),
        commitment_k: verifiable.then_some(tenzro_model::DEFAULT_COMMITMENT_K),
        ..GenerationConfig::default()
    };

    if is_local {
        // === Local inference ===
        let model_runtime = node.model_runtime.as_ref().ok_or_else(|| JsonRpcError {
            code: -32000,
            message: "Model runtime not initialized".to_string(),
            data: None,
        })?;

        if !model_runtime.is_loaded(&model_id) {
            return Err(JsonRpcError {
                code: -32000,
                message: format!("Model '{}' is not currently serving", model_id),
                data: None,
            });
        }

        // Acquire load slot (RAII guard auto-decrements on drop)
        let _load_guard = node.load_tracker.try_acquire(&model_id).map_err(|_| {
            let load_data = node.load_tracker.snapshot(&model_id).map(|s| {
                serde_json::json!({
                    "active_requests": s.active_requests,
                    "max_concurrent": s.max_concurrent,
                    "load_level": s.load_level.to_string(),
                })
            });
            JsonRpcError {
                code: -32000,
                message: format!("Model '{}' is at capacity. Try again later.", model_id),
                data: load_data,
            }
        })?;

        // Use generate_chat with proper chat template formatting
        let chat_messages = vec![ModelChatMessage {
            role: "user".to_string(),
            content: message.to_string(),
        }];

        let result = model_runtime
            .generate_chat(&model_id, &chat_messages, &config)
            .await
            .map_err(|e| {
                tracing::warn!(model = %model_id, error = %e, "Local inference failed");
                JsonRpcError {
                    code: -32000,
                    message: sanitize_model_error(&e),
                    data: None,
                }
            })?;

        // Record Prometheus inference counter for observability
        node.metrics().record_inference();

        // Refresh last_seen on successful inference so the 1-hour idle TTL
        // is bound to real usage rather than registration time.
        node.touch_local_model_service(&model_id);

        let pricing = node.provider_pricing.read();
        let cost_wei = (result.input_tokens as u128)
            .saturating_mul(pricing.input_price_per_token_wei)
            .saturating_add(
                (result.output_tokens as u128)
                    .saturating_mul(pricing.output_price_per_token_wei),
            );
        drop(pricing);

        let settlement = settle_inference_cost(
            node,
            params.get("caller_address").and_then(|v| v.as_str()),
            params.get("channel_id").and_then(|v| v.as_str()),
            params.get("channel_update_sig").and_then(|v| v.as_str()),
            &model_id,
            cost_wei,
        )?;

        // Build load snapshot for response
        let load = node.load_tracker.snapshot(&model_id).map(|s| {
            serde_json::json!({
                "active_requests": s.active_requests,
                "max_concurrent": s.max_concurrent,
                "utilization_percent": s.utilization_percent,
                "load_level": s.load_level.to_string(),
            })
        });

        // Stamp the output with a signed provenance manifest when this node
        // has a response signer. Optional by default; enforced only when the
        // caller asked for a verified response.
        let provenance = sign_local_response(node, &model_id, result.text.as_bytes());
        if require_signed && provenance.is_none() {
            return Err(JsonRpcError {
                code: -32022,
                message: "require_signed requested but this node has no response signer"
                    .to_string(),
                data: None,
            });
        }

        // Persist the TOPLOC commitment (when produced) and surface its
        // hash so the caller can verify or challenge the response later.
        let commitment = store_local_commitment(node, &model_id, result.commitment.as_ref());

        Ok(serde_json::json!({
            "output": result.text,
            "input_tokens": result.input_tokens,
            "output_tokens": result.output_tokens,
            "generation_time_ms": result.generation_time_ms,
            "tokens_per_second": result.tokens_per_second,
            "cost_wei": cost_wei.to_string(),
            "settlement": settlement.to_json(),
            "model_id": model_id,
            "location": "local",
            "load": load,
            "tenzro_provenance": provenance,
            "commitment": commitment,
        }))
    } else if let Some(ref svc) = service {
        // === Network model — forward to remote provider ===
        //
        // Peer-identity path first: dial the provider's iroh `EndpointId`
        // (Pkarr-resolved, NAT-agnostic) on the `tenzro/infer` ALPN. This is
        // the only path that works when the provider advertises a loopback
        // `rpc_endpoint` (every non-RPC-public and every NATed node does).
        // HTTP is the fallback, and only for providers that advertise a
        // genuinely reachable `rpc_endpoint`.
        let forward_params = serde_json::json!({
            "model_id": svc.model_id,
            "message": message,
            "max_tokens": config.max_tokens,
            "temperature": config.temperature,
            "require_signed": require_signed,
            "verifiable": verifiable,
        });
        let forward_body = serde_json::json!({
            "jsonrpc": "2.0",
            "method": "tenzro_chat",
            "params": forward_params,
            "id": 1,
        });

        let body: Value = forward_network_chat(
            node,
            net_iroh_endpoint_id.as_deref(),
            &svc.api_endpoint,
            &svc.provider_name,
            &forward_body,
        )
        .await?;

        // Extract output from JSON-RPC response
        let rpc_result = body.get("result").unwrap_or(&body);
        let output = rpc_result
            .get("output")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        let input_tokens = rpc_result.get("input_tokens").and_then(|v| v.as_u64()).unwrap_or(0);
        let output_tokens = rpc_result.get("output_tokens").and_then(|v| v.as_u64()).unwrap_or(0);

        // Verify any provider-attached provenance manifest against the key
        // pinned from the provider's signed gossip announcement. Invalid or
        // missing manifests are dropped; they only fail the request when the
        // caller explicitly asked for a verified response.
        let pinned = pinned_announcement_pubkey(node, &model_id, &svc.provider_name);
        let provenance = verify_forwarded_provenance(
            rpc_result.get("tenzro_provenance"),
            output.as_bytes(),
            &model_id,
            pinned.as_deref(),
            &svc.provider_name,
        );
        if require_signed && provenance.is_none() {
            return Err(JsonRpcError {
                code: -32022,
                message: format!(
                    "Provider {} did not return a verifiable signed response (require_signed)",
                    svc.provider_name
                ),
                data: None,
            });
        }

        // Record Prometheus inference counter for observability
        node.metrics().record_inference();

        Ok(serde_json::json!({
            "output": output,
            "input_tokens": input_tokens,
            "output_tokens": output_tokens,
            "model_id": model_id,
            "location": "network",
            "provider": svc.provider_name,
            "tenzro_provenance": provenance,
            // The provider persists the commitment; the hash rides through
            // so the caller can file a challenge against that provider.
            "commitment": rpc_result.get("commitment").cloned().unwrap_or(Value::Null),
        }))
    } else {
        Err(JsonRpcError {
            code: -32000,
            message: format!("Model '{}' not found. Use tenzro_listModels to see available models.", model_query),
            data: None,
        })
    }
}

/// Rich-shape chat handler — multi-turn, system prompts, content blocks.
///
/// First implementation pass: text-only blocks. Tool-use parsing from the
/// raw output, vision input, and extended-thinking emission are added
/// in follow-up commits on this branch (see `docs/chat-api.md` for the
/// public contract).
///
/// What this pass supports today:
/// - Multi-turn conversation via `messages: [...]`.
/// - System prompt via top-level `system` (string or text-block array).
/// - Content blocks of type `text` on input.
/// - Content blocks of type `tool_use`/`tool_result` are accepted on input
///   and flattened to text for the model template (so existing agents that
///   already do client-side tool execution can still drive the model).
/// - Output is returned as a single `text` block in `content`, with
///   `stop_reason: "end_turn"` or `"max_tokens"`.
async fn handle_chat_rich(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use tenzro_types::model::{
        ContentBlock, RichChatMessage, RichUsage, SystemPrompt, ToolResultContent, ToolSchema,
    };

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    // ── parse model id ───────────────────────────────────────────────
    let model_query = params
        .get("model_id")
        .or_else(|| params.get("model"))
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'model_id' (or 'model') parameter".to_string(),
            data: None,
        })?;

    // ── parse messages array ─────────────────────────────────────────
    let messages_value = params.get("messages").ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing 'messages' parameter".to_string(),
        data: None,
    })?;
    let messages: Vec<RichChatMessage> = serde_json::from_value(messages_value.clone())
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("Invalid 'messages' shape: {}", e),
            data: None,
        })?;
    if messages.is_empty() {
        return Err(JsonRpcError {
            code: -32602,
            message: "'messages' must contain at least one message".to_string(),
            data: None,
        });
    }
    tenzro_types::validation::validate_vec_len(
        &messages, "messages", tenzro_types::validation::MAX_CHAT_MESSAGES,
    ).map_err(|e| JsonRpcError { code: -32602, message: e.to_string(), data: None })?;
    for (i, m) in messages.iter().enumerate() {
        tenzro_types::validation::validate_numeric_bound(
            m.payload_len(),
            &format!("message[{}] content", i),
            tenzro_types::validation::MAX_CHAT_MESSAGE_LEN,
        ).map_err(|e| JsonRpcError { code: -32602, message: e.to_string(), data: None })?;
    }

    // ── parse optional system prompt ─────────────────────────────────
    let system: Option<SystemPrompt> = match params.get("system") {
        Some(v) => Some(serde_json::from_value(v.clone()).map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("Invalid 'system' shape: {}", e),
            data: None,
        })?),
        None => None,
    };

    // ── parse optional tools (validated, used by template; tool_use
    //    extraction from output lands in a follow-up commit) ──────────
    let tools: Vec<ToolSchema> = match params.get("tools") {
        Some(v) => serde_json::from_value(v.clone()).map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("Invalid 'tools' shape: {}", e),
            data: None,
        })?,
        None => Vec::new(),
    };
    for t in &tools {
        if !is_valid_tool_name(&t.name) {
            return Err(JsonRpcError {
                code: -32602,
                message: format!(
                    "Invalid tool name '{}': must match ^[a-zA-Z0-9_-]{{1,64}}$",
                    t.name
                ),
                data: None,
            });
        }
        if !t.input_schema.is_object() {
            return Err(JsonRpcError {
                code: -32602,
                message: format!(
                    "Tool '{}' input_schema must be a JSON Schema object",
                    t.name
                ),
                data: None,
            });
        }
    }

    // ── resolve model service (local or network) ─────────────────────
    let mut service = node.get_model_service(model_query)
        .or_else(|| node.find_model_service_by_model_id(model_query));

    // Provider iroh `EndpointId` for a network-resolved model (see the
    // simple-shape handler for the full rationale). Threaded as a sibling
    // because `ModelServiceInstance` carries no iroh field.
    let mut net_iroh_endpoint_id: Option<String> = None;

    if service.is_none() && !node.served_models.contains_key(model_query) {
        let own_endpoint_id = node
            .iroh_resolver
            .as_ref()
            .map(|r| r.endpoint_id().to_string());

        for entry in node.network_models_snapshot() {
            let reg = &entry.registration;
            if reg.model_id == model_query {
                // Self-dial guard: skip our own announcement.
                let is_self = own_endpoint_id
                    .as_deref()
                    .is_some_and(|own| !reg.iroh_endpoint_id.is_empty()
                        && reg.iroh_endpoint_id == own);
                if is_self {
                    continue;
                }
                net_iroh_endpoint_id = if reg.iroh_endpoint_id.is_empty() {
                    None
                } else {
                    Some(reg.iroh_endpoint_id.clone())
                };
                service = Some(tenzro_types::model::ModelServiceInstance {
                    instance_id: format!("net-{}-{}", reg.model_id, reg.provider),
                    model_id: reg.model_id.clone(),
                    model_name: reg.name.clone(),
                    provider_address: tenzro_types::primitives::Address::from_hex(&reg.provider)
                        .unwrap_or_default(),
                    provider_name: reg.provider.clone(),
                    location: tenzro_types::model::ModelLocation::Network,
                    api_endpoint: reg.rpc_endpoint.clone(),
                    mcp_endpoint: String::new(),
                    status: tenzro_types::model::ServiceStatus::Online,
                    parameters: reg.parameters.clone(),
                    pricing: tenzro_types::model::PricingConfig {
                        price_per_input_token: reg.pricing.per_token.unwrap_or(0),
                        price_per_output_token: reg.pricing.per_token.unwrap_or(0),
                        minimum_price: reg.pricing.per_request,
                        pricing_model: tenzro_types::model::PricingModel::PerToken,
                    },
                    created_at: 0,
                    last_seen: std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_secs(),
                    load_info: None,
                    iroh_endpoint_id: reg.iroh_endpoint_id.clone(),
                });
                break;
            }
        }
    }

    let is_local = if let Some(ref svc) = service {
        svc.location == ModelLocation::Local
    } else {
        node.served_models.contains_key(model_query)
    };

    let model_id = if let Some(ref svc) = service {
        svc.model_id.clone()
    } else {
        model_query.to_string()
    };

    // ── parse generation config ──────────────────────────────────────
    let max_tokens = params
        .get("max_tokens")
        .and_then(|v| v.as_u64())
        .unwrap_or(1024);
    tenzro_types::validation::validate_numeric_bound(
        max_tokens, "max_tokens", tenzro_types::validation::MAX_INFERENCE_TOKENS,
    ).map_err(|e| JsonRpcError { code: -32602, message: e.to_string(), data: None })?;
    let max_tokens = max_tokens as u32;
    let temperature = params.get("temperature").and_then(|v| v.as_f64()).unwrap_or(0.7);
    tenzro_types::validation::validate_temperature(temperature)
        .map_err(|e| JsonRpcError { code: -32602, message: e.to_string(), data: None })?;
    // Opt-in verifiable-inference mode (TOPLOC scheme) — same contract as
    // the simple-shape handler: the serving runtime commits to top-k
    // logits per generated token and the response carries the commitment
    // hash for later challenge.
    let verifiable = params
        .get("verifiable")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let config = GenerationConfig {
        temperature,
        top_p: params.get("top_p").and_then(|v| v.as_f64()).unwrap_or(0.9),
        max_tokens,
        repeat_penalty: params
            .get("repeat_penalty")
            .and_then(|v| v.as_f64())
            .unwrap_or(1.1) as f32,
        draft_n: params
            .get("draft_n")
            .and_then(|v| v.as_u64())
            .and_then(|n| u8::try_from(n).ok())
            .filter(|n| (1..=6).contains(n)),
        commitment_k: verifiable.then_some(tenzro_model::DEFAULT_COMMITMENT_K),
        ..GenerationConfig::default()
    };

    if is_local {
        // ── local inference path ─────────────────────────────────────
        let model_runtime = node.model_runtime.as_ref().ok_or_else(|| JsonRpcError {
            code: -32000,
            message: "Model runtime not initialized".to_string(),
            data: None,
        })?;

        if !model_runtime.is_loaded(&model_id) {
            return Err(JsonRpcError {
                code: -32000,
                message: format!("Model '{}' is not currently serving", model_id),
                data: None,
            });
        }

        let _load_guard = node.load_tracker.try_acquire(&model_id).map_err(|_| {
            let load_data = node.load_tracker.snapshot(&model_id).map(|s| {
                serde_json::json!({
                    "active_requests": s.active_requests,
                    "max_concurrent": s.max_concurrent,
                    "load_level": s.load_level.to_string(),
                })
            });
            JsonRpcError {
                code: -32000,
                message: format!("Model '{}' is at capacity. Try again later.", model_id),
                data: load_data,
            }
        })?;

        // Flatten rich messages into the existing ChatMessage format the
        // runtime accepts. Tool-use, tool-result, and thinking blocks are
        // stringified into the message text for now — the model still sees
        // them, just as inline annotations rather than structured blocks.
        let mut chat_messages: Vec<ModelChatMessage> = Vec::new();
        if let Some(sys) = &system {
            chat_messages.push(ModelChatMessage {
                role: "system".to_string(),
                content: sys.as_text(),
            });
        }
        for m in &messages {
            chat_messages.push(ModelChatMessage {
                role: m.role.clone(),
                content: render_blocks_as_text(&m.content),
            });
        }

        // Dispatch: if tools are present, run the tool-aware path so the
        // model sees schemas and we can extract structured tool calls
        // from the output. Otherwise fall through to plain chat
        // generation. Both paths exercise real llama.cpp inference.
        let (
            response_text,
            extracted_tool_calls,
            input_tokens,
            output_tokens,
            inferred_stop_reason,
            result_commitment,
        ) = if !tools.is_empty() {
            let runtime_tools: Vec<RuntimeToolDefinition> = tools
                .iter()
                .map(|t| RuntimeToolDefinition {
                    name: t.name.clone(),
                    description: if t.description.is_empty() {
                        None
                    } else {
                        Some(t.description.clone())
                    },
                    input_schema: t.input_schema.clone(),
                })
                .collect();

            let r = model_runtime
                .generate_chat_with_tools(&model_id, &chat_messages, &runtime_tools, &config)
                .await
                .map_err(|e| {
                    tracing::warn!(model = %model_id, error = %e, "Local inference failed");
                    JsonRpcError {
                        code: -32000,
                        message: sanitize_model_error(&e),
                        data: None,
                    }
                })?;
            (
                r.text,
                r.tool_calls,
                r.input_tokens,
                r.output_tokens,
                r.stop_reason,
                r.commitment,
            )
        } else {
            let r = model_runtime
                .generate_chat(&model_id, &chat_messages, &config)
                .await
                .map_err(|e| {
                    tracing::warn!(model = %model_id, error = %e, "Local inference failed");
                    JsonRpcError {
                        code: -32000,
                        message: sanitize_model_error(&e),
                        data: None,
                    }
                })?;
            let stop = if r.output_tokens >= max_tokens {
                "max_tokens".to_string()
            } else {
                "end_turn".to_string()
            };
            (r.text, Vec::new(), r.input_tokens, r.output_tokens, stop, r.commitment)
        };

        node.metrics().record_inference();
        node.touch_local_model_service(&model_id);

        // ── build response ───────────────────────────────────────────
        let pricing = node.provider_pricing.read();
        let cost_wei = (input_tokens as u128)
            .saturating_mul(pricing.input_price_per_token_wei)
            .saturating_add(
                (output_tokens as u128).saturating_mul(pricing.output_price_per_token_wei),
            );
        drop(pricing);

        let settlement = settle_inference_cost(
            node,
            params.get("caller_address").and_then(|v| v.as_str()),
            params.get("channel_id").and_then(|v| v.as_str()),
            params.get("channel_update_sig").and_then(|v| v.as_str()),
            &model_id,
            cost_wei,
        )?;

        // Map the inferred string stop reason onto the typed enum.
        let stop_reason = map_stop_reason(&inferred_stop_reason);

        let usage = RichUsage {
            input_tokens,
            output_tokens,
            cache_creation_input_tokens: 0,
            cache_read_input_tokens: 0,
        };

        // Build content blocks: any free text (non-empty after stripping
        // tool-call markers) plus each extracted ToolUse in emission order.
        let mut content: Vec<ContentBlock> = Vec::new();
        if !response_text.trim().is_empty() {
            content.push(ContentBlock::Text {
                text: response_text,
                cache_control: None,
            });
        }
        for tc in extracted_tool_calls {
            content.push(ContentBlock::ToolUse {
                id: tc.id,
                name: tc.name,
                input: tc.input,
            });
        }
        if content.is_empty() {
            // Always return at least one block so consumers can render.
            content.push(ContentBlock::Text {
                text: String::new(),
                cache_control: None,
            });
        }

        // ToolResultContent is part of the schema we accept on input; the
        // reference here keeps the import live and avoids dead-code lint.
        let _ = ToolResultContent::Text(String::new());
        let _ = &messages;

        // Persist the TOPLOC commitment (when produced) and surface its
        // hash so the caller can verify or challenge the response later.
        let commitment = store_local_commitment(node, &model_id, result_commitment.as_ref());

        Ok(serde_json::json!({
            "id": format!("msg_{}", uuid::Uuid::new_v4().simple()),
            "model": model_id,
            "role": "assistant",
            "content": content,
            "stop_reason": stop_reason,
            "stop_sequence": serde_json::Value::Null,
            "usage": usage,
            "cost_wei": cost_wei.to_string(),
            "settlement": settlement.to_json(),
            "location": "local",
            "commitment": commitment,
            "load": node.load_tracker.snapshot(&model_id).map(|s| {
                serde_json::json!({
                    "active_requests": s.active_requests,
                    "max_concurrent": s.max_concurrent,
                    "utilization_percent": s.utilization_percent,
                    "load_level": s.load_level.to_string(),
                })
            }),
        }))
    } else if let Some(ref svc) = service {
        // ── network forwarding path ──────────────────────────────────
        // Spec requires the rich shape to forward intact — no
        // down-conversion. We forward `messages`, `system`, `tools`, and
        // generation config verbatim. Peer-identity (iroh) first, then HTTP
        // fallback — see `forward_network_chat`.
        let mut forward_params = serde_json::Map::new();
        forward_params.insert("model_id".to_string(), serde_json::json!(svc.model_id));
        forward_params.insert("messages".to_string(), messages_value.clone());
        if let Some(sys) = params.get("system") {
            forward_params.insert("system".to_string(), sys.clone());
        }
        if !tools.is_empty()
            && let Some(t) = params.get("tools") {
                forward_params.insert("tools".to_string(), t.clone());
            }
        forward_params.insert("max_tokens".to_string(), serde_json::json!(config.max_tokens));
        forward_params.insert(
            "temperature".to_string(),
            serde_json::json!(config.temperature),
        );
        forward_params.insert("top_p".to_string(), serde_json::json!(config.top_p));
        if let Some(stop) = params.get("stop_sequences") {
            forward_params.insert("stop_sequences".to_string(), stop.clone());
        }
        if let Some(re) = params.get("reasoning_effort") {
            forward_params.insert("reasoning_effort".to_string(), re.clone());
        }
        if let Some(caller) = params.get("caller_address") {
            forward_params.insert("caller_address".to_string(), caller.clone());
        }
        if verifiable {
            // The provider persists the commitment; its `commitment` field
            // rides back through the verbatim result pass-through below.
            forward_params.insert("verifiable".to_string(), serde_json::json!(true));
        }

        let forward_body = serde_json::json!({
            "jsonrpc": "2.0",
            "method": "tenzro_chat",
            "params": Value::Object(forward_params),
            "id": 1,
        });

        let body: Value = forward_network_chat(
            node,
            net_iroh_endpoint_id.as_deref(),
            &svc.api_endpoint,
            &svc.provider_name,
            &forward_body,
        )
        .await?;

        node.metrics().record_inference();

        // Pass the provider's result through, annotating location.
        if let Some(rpc_result) = body.get("result") {
            let mut out = rpc_result.clone();
            if let Some(obj) = out.as_object_mut() {
                obj.insert("location".to_string(), serde_json::json!("network"));
                obj.insert("provider".to_string(), serde_json::json!(svc.provider_name));
            }
            Ok(out)
        } else if let Some(err) = body.get("error") {
            Err(JsonRpcError {
                code: -32000,
                message: format!("Provider error: {}", err),
                data: None,
            })
        } else {
            Err(JsonRpcError {
                code: -32000,
                message: "Provider returned malformed JSON-RPC response".to_string(),
                data: None,
            })
        }
    } else {
        Err(JsonRpcError {
            code: -32000,
            message: format!(
                "Model '{}' not found. Use tenzro_listModels to see available models.",
                model_query
            ),
            data: None,
        })
    }
}

/// Validates a tool name against the spec rule `^[a-zA-Z0-9_-]{1,64}$`.
fn is_valid_tool_name(name: &str) -> bool {
    if name.is_empty() || name.len() > 64 {
        return false;
    }
    name.chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
}

/// Map the runtime's stop_reason string to the typed `StopReason` enum.
/// Anything unrecognized maps to `EndTurn`.
fn map_stop_reason(s: &str) -> tenzro_types::model::StopReason {
    use tenzro_types::model::StopReason;
    match s {
        "tool_use" => StopReason::ToolUse,
        "max_tokens" => StopReason::MaxTokens,
        "stop_sequence" => StopReason::StopSequence,
        _ => StopReason::EndTurn,
    }
}

/// Render a `MessageContent` value (string or block array) as a flat
/// text string suitable for chat templates that don't yet understand
/// content blocks. Tool-use and tool-result blocks are inlined as
/// JSON-tagged text so the model still sees the structure.
fn render_blocks_as_text(content: &tenzro_types::model::MessageContent) -> String {
    use tenzro_types::model::{ContentBlock, MessageContent, ToolResultContent};
    let blocks = match content {
        MessageContent::Text(s) => return s.clone(),
        MessageContent::Blocks(b) => b,
    };
    let mut out = String::new();
    for b in blocks {
        match b {
            ContentBlock::Text { text, .. } => out.push_str(text),
            ContentBlock::Thinking { thinking } => {
                out.push_str("<thinking>");
                out.push_str(thinking);
                out.push_str("</thinking>");
            }
            ContentBlock::ToolUse { id, name, input } => {
                out.push_str(&format!(
                    "<tool_use id=\"{}\" name=\"{}\">{}</tool_use>",
                    id,
                    name,
                    serde_json::to_string(input).unwrap_or_default()
                ));
            }
            ContentBlock::ToolResult {
                tool_use_id,
                content,
                is_error,
            } => {
                let body = match content {
                    ToolResultContent::Text(s) => s.clone(),
                    ToolResultContent::Blocks(blocks) => blocks
                        .iter()
                        .filter_map(|b| match b {
                            ContentBlock::Text { text, .. } => Some(text.clone()),
                            _ => None,
                        })
                        .collect::<Vec<_>>()
                        .join(""),
                };
                let err_attr = if matches!(is_error, Some(true)) {
                    " is_error=\"true\""
                } else {
                    ""
                };
                out.push_str(&format!(
                    "<tool_result id=\"{}\"{}>{}</tool_result>",
                    tool_use_id, err_attr, body
                ));
            }
            ContentBlock::Image { .. } => {
                out.push_str("[image]");
            }
        }
    }
    out
}

// Delete model handler
async fn handle_delete_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let model_id = params
        .get("model_id")
        .or_else(|| params.as_array().and_then(|a| a.first()).and_then(|v| v.get("model_id")))
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'model_id' parameter".to_string(),
            data: None,
        })?;

    // Unload from runtime if serving
    if let Some(runtime) = &node.model_runtime
        && runtime.is_loaded(model_id) {
            let _ = runtime.unload_model(model_id).await;
        }

    // Delete the GGUF file from disk
    if let Some(hf_dl) = &node.hf_downloader {
        hf_dl.delete_model(model_id).map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Failed to delete model file: {}", e),
            data: None,
        })?;
    }

    // Remove from downloads, served models, and service registry
    node.model_downloads.remove(model_id);
    node.served_models.remove(model_id);
    node.unregister_model_services_by_model(model_id);

    Ok(serde_json::json!({
        "success": true,
        "model_id": model_id,
        "status": "deleted",
    }))
}

// List providers handler
async fn handle_list_providers(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let mut seen_ids: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut result: Vec<serde_json::Value> = Vec::new();

    // Include self as a provider if we're serving models locally
    let served: Vec<String> = node.served_models
        .iter()
        .filter(|e| *e.value())
        .map(|e| e.key().clone())
        .collect();

    if !served.is_empty() {
        let self_peer_id = "local".to_string();
        seen_ids.insert(self_peer_id.clone());
        result.push(serde_json::json!({
            "peer_id": self_peer_id,
            "provider_address": "0x0000000000000000000000000000000000000000",
            "provider_type": "llm",
            "served_models": served,
            "capabilities": ["inference"],
            "rpc_endpoint": "",
            "status": "active",
            "timestamp": chrono::Utc::now().timestamp_millis(),
            "source": "local",
        }));
    }

    // Merge network providers discovered via gossipsub (dedup by peer_id; local takes precedence)
    for entry in node.network_providers_snapshot() {
        let peer_id = entry.announcement.peer_id.clone();
        if !seen_ids.contains(&peer_id) {
            seen_ids.insert(peer_id.clone());
            result.push(serde_json::json!({
                "peer_id": peer_id,
                "provider_address": entry.announcement.provider_address,
                "provider_type": entry.announcement.provider_type,
                "served_models": entry.announcement.served_models,
                "capabilities": entry.announcement.capabilities,
                "rpc_endpoint": entry.announcement.rpc_endpoint,
                "status": entry.announcement.status,
                "timestamp": entry.announcement.timestamp,
                "reachability": entry.announcement.network_profile.reachability,
                "source": "network",
            }));
        }
    }

    Ok(serde_json::to_value(result).unwrap_or(serde_json::json!([])))
}

/// Network-wide provider-capacity discovery.
///
/// For every provider this node knows about — its own registered entry plus
/// every gossip-discovered peer in `network_providers_snapshot()` — this joins
/// the *advertised* serving capacity (declared by the provider on its
/// announcement / registration) with the *measured* serving performance
/// (realized throughput + latency + reputation this node has observed). Both
/// are returned side by side, plus a reputation-discounted throughput figure
/// so a caller ranking providers sees the declared ceiling and the number the
/// network actually trusts.
async fn handle_list_provider_capacity(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let pm = node.provider_manager();
    let tracker = node.usage_tracker();

    // Look up the measured side for one provider address.
    let measured_for = |addr: &Address| -> Value {
        let metrics = pm.and_then(|pm| pm.get_metrics(addr).ok());
        let reputation = pm.and_then(|pm| pm.get_reputation(addr));
        let usage = tracker.and_then(|t| t.get_provider_stats(addr));

        let measured_tps = usage.as_ref().and_then(|u| u.measured_tokens_per_sec());
        // Reputation is 0..=1000; discount the measured throughput by the
        // provider's trust so the ranking figure reflects observed reliability.
        let trust = reputation.map(|r| (r as f64 / 1000.0).clamp(0.0, 1.0));
        let trusted_tps = match (measured_tps, trust) {
            (Some(tps), Some(t)) => Some(tps * t),
            _ => None,
        };

        serde_json::json!({
            "total_requests": metrics.as_ref().map(|m| m.total_requests),
            "successful_requests": metrics.as_ref().map(|m| m.successful_requests),
            "failed_requests": metrics.as_ref().map(|m| m.failed_requests),
            "avg_latency_ms": metrics.as_ref().map(|m| m.avg_latency_ms),
            "p95_latency_ms": metrics.as_ref().and_then(|m| m.latency_p95_ms()),
            "uptime_percentage": metrics.as_ref().map(|m| m.uptime_percentage),
            "reputation": reputation,
            "inference_count": usage.as_ref().map(|u| u.inference_count),
            "total_output_tokens": usage.as_ref().map(|u| u.total_output_tokens),
            "measured_tokens_per_sec": measured_tps,
            "reputation_discounted_tokens_per_sec": trusted_tps,
            "total_revenue_wei": usage.as_ref().map(|u| u.total_revenue.to_string()),
        })
    };

    let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut result: Vec<Value> = Vec::new();

    // This node's own registered providers (locally served).
    if let Some(pm) = pm {
        for provider in pm.list_providers() {
            let addr = provider.address;
            let addr_hex = addr.to_string();
            seen.insert(addr_hex.clone());
            let cap = &provider.capacity;
            result.push(serde_json::json!({
                "provider_address": addr_hex,
                "source": "local",
                "status": format!("{:?}", provider.status),
                "served_models": provider.models,
                "advertised": {
                    "max_concurrent_requests": cap.max_concurrent_requests,
                    "active_requests": cap.active_requests,
                    "requests_per_second": cap.requests_per_second,
                    "max_batch_size": cap.max_batch_size,
                    "mtp_enabled": cap.mtp_enabled,
                    "verifiable_inference": cap.verifiable_inference,
                    "utilization_pct": cap.utilization(),
                },
                "measured": measured_for(&addr),
            }));
        }
    }

    // Gossip-discovered peers, deduped against local entries.
    for entry in node.network_providers_snapshot() {
        let ann = &entry.announcement;
        let addr = match Address::from_hex(
            ann.provider_address.strip_prefix("0x").unwrap_or(&ann.provider_address),
        ) {
            Ok(a) => a,
            Err(_) => continue,
        };
        let addr_hex = addr.to_string();
        if seen.contains(&addr_hex) {
            continue;
        }
        seen.insert(addr_hex.clone());
        let cap = &ann.capacity;
        result.push(serde_json::json!({
            "provider_address": addr_hex,
            "peer_id": ann.peer_id,
            "source": "network",
            "status": ann.status,
            "served_models": ann.served_models,
            "rpc_endpoint": ann.rpc_endpoint,
            "reachability": ann.network_profile.reachability,
            "advertised": {
                "max_concurrent_requests": cap.max_concurrent_requests,
                "active_requests": cap.active_requests,
                "requests_per_second": cap.requests_per_second,
                "max_batch_size": cap.max_batch_size,
                "mtp_enabled": cap.mtp_enabled,
                "verifiable_inference": cap.verifiable_inference,
            },
            "measured": measured_for(&addr),
        }));
    }

    Ok(serde_json::json!({ "providers": result, "count": result.len() }))
}

// Add resource handler
async fn handle_add_resource(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    // Support both array and object params
    let resource_obj = if let Some(arr) = params.as_array() {
        arr.first().unwrap_or(&params)
    } else {
        &params
    };

    let resource_type = resource_obj
        .get("resource_type")
        .and_then(|v| v.as_str())
        .unwrap_or("model")
        .to_string();

    let resource_id = resource_obj
        .get("resource_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'resource_id' parameter".to_string(),
            data: None,
        })?
        .to_string();

    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let resource = UserResource {
        resource_type,
        resource_id: resource_id.clone(),
        added_at: now,
    };

    node.user_resources.insert(resource_id.clone(), resource);

    Ok(serde_json::json!({
        "success": true,
        "resource_id": resource_id,
    }))
}

/// Submit a finalized block to the event loop for execution
async fn handle_submit_block(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    // Deserialize the block from JSON
    let block: Block = serde_json::from_value(params).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid block data: {}", e),
        data: None,
    })?;

    let block_hash = format!("{}", block.hash());
    let block_height = block.height();
    let tx_count = block.tx_count();

    node.submit_block(block).await.map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Failed to submit block: {}", e),
        data: None,
    })?;

    Ok(serde_json::json!({
        "status": "submitted",
        "block_hash": block_hash,
        "block_height": block_height,
        "tx_count": tx_count,
    }))
}

// Get transaction history handler
async fn handle_get_transaction_history(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let _address = params
        .as_ref()
        .and_then(|p| {
            if let Some(arr) = p.as_array() {
                arr.first().and_then(|v| v.get("address")).and_then(|v| v.as_str())
            } else {
                p.get("address").and_then(|v| v.as_str())
            }
        });

    let history = node.transaction_history.read().clone();

    serde_json::to_value(&history).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Serialization failed: {}", e),
        data: None,
    })
}

// === OpenAI-compatible API handlers ===

/// OpenAI-compatible request body for /v1/chat/completions
#[derive(Debug, Deserialize)]
struct OpenAIChatRequest {
    model: String,
    messages: Vec<OpenAIChatMessage>,
    #[serde(default)]
    temperature: Option<f64>,
    #[serde(default)]
    max_tokens: Option<u32>,
    #[serde(default)]
    top_p: Option<f64>,
    #[serde(default)]
    stream: Option<bool>,
    /// Tenzro extension: Multi-Token-Prediction draft count (1..=6).
    /// Out-of-band on the OpenAI schema but tolerated by every client
    /// since it's an unknown field. Tenzro-aware clients can opt in
    /// to MTP throughput on supported models.
    #[serde(default)]
    draft_n: Option<u8>,
    /// Tenzro extension: request a TOPLOC top-k logit commitment with the
    /// response. Non-streaming requests served by the local single-token
    /// path return a `commitment` object (hash + k + steps) that the caller
    /// can later dispute via `tenzro_fileInferenceChallenge`. Streaming
    /// responses and external-engine backends carry no commitment.
    #[serde(default)]
    verifiable: Option<bool>,
}

#[derive(Debug, Deserialize, Serialize)]
struct OpenAIChatMessage {
    role: String,
    content: String,
}

/// Context window + max output tokens for a model, resolved from the
/// registry's `ModelInfo.parameters` first (authoritative for registered
/// models) and the static language catalog second (covers catalog models a
/// provider serves without a registry row). `(None, None)` means the model is
/// unknown to both — callers surface `null` rather than a guessed number.
fn model_context_limits(node: &Arc<TenzroNode>, model_id: &str) -> (Option<u32>, Option<u32>) {
    if let Some(registry) = node.model_registry()
        && let Ok(info) = registry.get_model(model_id)
    {
        return (
            Some(info.parameters.context_window),
            Some(info.parameters.max_output_tokens),
        );
    }
    if let Some(entry) = tenzro_model::get_model_by_id(model_id) {
        return (Some(entry.context_length), None);
    }
    (None, None)
}

/// Declared datacenter geography for a provider address, resolved from its
/// gossip announcement. `None` means the operator declined to declare a
/// region — consumers must treat that as unknown, not wildcard.
fn provider_geography(node: &Arc<TenzroNode>, provider: &str) -> Option<String> {
    let wanted = provider.strip_prefix("0x").unwrap_or(provider);
    node.network_providers_snapshot().into_iter().find_map(|entry| {
        let ann = &entry.announcement;
        let addr = ann.provider_address.strip_prefix("0x").unwrap_or(&ann.provider_address);
        if addr.eq_ignore_ascii_case(wanted) {
            ann.geography.clone()
        } else {
            None
        }
    })
}

/// The gateway's machine-readable data-handling declaration, derived from
/// what the serving path actually does: prompt/completion bodies are never
/// written to disk; SSE chunks live in an in-memory resume buffer bounded by
/// the cursor TTL; the usage tracker records token counts, cost, and latency
/// only. Aggregators consume this alongside the per-model listing.
fn openai_data_policy() -> Value {
    serde_json::json!({
        "prompt_retention": "none",
        "completion_retention": "none",
        "stream_resume_buffer_secs": crate::streaming::DEFAULT_TTL.as_secs(),
        "trains_on_data": false,
        "usage_accounting": "token_counts_cost_latency_only",
    })
}

/// Feature flags + supported sampling parameters for one model, derived from
/// the serving path: streaming and usage-in-stream are unconditional on this
/// gateway; MTP reflects the catalog's speculative-decoding capability;
/// provenance signing reflects whether this node has a provenance signer
/// bound (local responses carry a signed `tenzro_provenance` manifest).
fn openai_model_features(node: &Arc<TenzroNode>, model_id: &str, local: bool) -> Value {
    let mtp_capable = tenzro_model::get_model_by_id(model_id)
        .is_some_and(|e| e.mtp_kind != tenzro_model::MtpKind::None);
    serde_json::json!({
        "streaming": true,
        "usage_in_stream": true,
        "mtp": mtp_capable,
        "provenance_signing": local && node.provenance_signer().is_some(),
        "supported_parameters": ["temperature", "top_p", "max_tokens", "stream", "draft_n", "verifiable"],
    })
}

/// Best-effort projection of a catalog GGUF quantization tag onto the coarse
/// int4/int8/fp16/bf16/fp32 vocabulary aggregators expect. Tags without an
/// unambiguous bit-width equivalent (Q5/Q6 k-quants, IQ variants) yield
/// `Value::Null` — over- or under-stating precision is worse than omitting.
fn quantization_label(model_id: &str) -> Value {
    let Some(entry) = tenzro_model::get_model_by_id(model_id) else {
        return Value::Null;
    };
    let tag = entry.quantization.to_ascii_uppercase();
    let label = if tag.starts_with("Q4") {
        "int4"
    } else if tag.starts_with("Q8") {
        "int8"
    } else if tag.starts_with("BF16") {
        "bf16"
    } else if tag.starts_with("F16") || tag.starts_with("FP16") {
        "fp16"
    } else if tag.starts_with("F32") || tag.starts_with("FP32") {
        "fp32"
    } else {
        return Value::Null;
    };
    Value::String(label.to_string())
}

/// Serialize one model-service instance as an enriched `/v1/models` entry:
/// the OpenAI core fields plus the serving contract an aggregator needs —
/// per-token pricing, context window, max output tokens, feature flags, and
/// declared datacenter geography. Everything is derived from registry /
/// announcement state; no operator-side listing configuration exists.
fn openai_model_entry(node: &Arc<TenzroNode>, svc: &tenzro_types::model::ModelServiceInstance) -> Value {
    let (context_length, max_output_tokens) = model_context_limits(node, &svc.model_id);
    let is_local = svc.location == ModelLocation::Local;
    let datacenter_location = if is_local {
        node.config().geography.clone()
    } else {
        provider_geography(node, &svc.provider_name)
    };
    serde_json::json!({
        "id": svc.instance_id,
        "object": "model",
        "created": svc.created_at,
        "owned_by": svc.provider_name,
        "model_id": svc.model_id,
        "model_name": svc.model_name,
        "location": svc.location.to_string(),
        "status": svc.status.to_string(),
        "parameters": svc.parameters,
        "input_modalities": ["text"],
        "output_modalities": ["text"],
        "quantization": quantization_label(&svc.model_id),
        "context_length": context_length,
        "max_output_tokens": max_output_tokens,
        "pricing": {
            "input_wei_per_token": svc.pricing.price_per_input_token.to_string(),
            "output_wei_per_token": svc.pricing.price_per_output_token.to_string(),
            "minimum_wei": svc.pricing.minimum_price.to_string(),
            "pricing_model": format!("{:?}", svc.pricing.pricing_model),
        },
        "features": openai_model_features(node, &svc.model_id, is_local),
        "datacenter_location": datacenter_location,
        "api_endpoint": svc.api_endpoint,
        "mcp_endpoint": svc.mcp_endpoint,
    })
}

/// Serialize one gossip-discovered model registration as an enriched
/// `/v1/models` entry. The `id` is the model_id — that is the string the
/// chat handler resolves through the network-models snapshot, so a client
/// can take any `id` from this listing and use it directly as
/// `request.model`.
fn openai_model_entry_from_registration(
    node: &Arc<TenzroNode>,
    reg: &tenzro_network::ModelRegistrationMessage,
) -> Value {
    let context_length = if reg.context_length > 0 {
        Some(reg.context_length)
    } else {
        model_context_limits(node, &reg.model_id).0
    };
    serde_json::json!({
        "id": reg.model_id,
        "object": "model",
        "created": reg.timestamp / 1000,
        "owned_by": reg.provider,
        "model_id": reg.model_id,
        "model_name": reg.name,
        "location": "network",
        "status": "online",
        "parameters": reg.parameters,
        "input_modalities": ["text"],
        "output_modalities": ["text"],
        "quantization": quantization_label(&reg.model_id),
        "context_length": context_length,
        "max_output_tokens": Value::Null,
        "pricing": {
            "input_wei_per_token": reg.pricing.per_token.unwrap_or(0).to_string(),
            "output_wei_per_token": reg.pricing.per_token.unwrap_or(0).to_string(),
            "minimum_wei": reg.pricing.per_request.to_string(),
            "pricing_model": "PerToken",
        },
        "features": openai_model_features(node, &reg.model_id, false),
        "datacenter_location": provider_geography(node, &reg.provider),
        "api_endpoint": reg.rpc_endpoint,
        "mcp_endpoint": "",
    })
}

/// GET /v1/models — every model this gateway can serve: local service
/// instances, registered network endpoints, and gossip-discovered models the
/// chat handler proxies to. Deduped by (model_id, provider).
async fn handle_openai_list_models(
    State(node): State<Arc<TenzroNode>>,
) -> impl IntoResponse {
    let mut seen: std::collections::HashSet<(String, String)> = std::collections::HashSet::new();
    let mut models: Vec<Value> = Vec::new();

    for svc in node.list_model_services() {
        seen.insert((svc.model_id.clone(), svc.provider_name.clone()));
        models.push(openai_model_entry(&node, &svc));
    }

    // Gossip-discovered models not registered as service instances. Skip our
    // own announcements — those are already listed as local services.
    let own_endpoint_id = node
        .iroh_resolver
        .as_ref()
        .map(|r| r.endpoint_id().to_string());
    for entry in node.network_models_snapshot() {
        let reg = &entry.registration;
        if seen.contains(&(reg.model_id.clone(), reg.provider.clone())) {
            continue;
        }
        let is_self = own_endpoint_id.as_deref().is_some_and(|own| {
            !reg.iroh_endpoint_id.is_empty() && reg.iroh_endpoint_id == own
        });
        if is_self {
            continue;
        }
        seen.insert((reg.model_id.clone(), reg.provider.clone()));
        models.push(openai_model_entry_from_registration(&node, reg));
    }

    Json(serde_json::json!({
        "object": "list",
        "data": models,
        "data_policy": openai_data_policy(),
    }))
}

/// GET /v1/models/{instance_id} — Get a specific model by instance ID
async fn handle_openai_get_model(
    State(node): State<Arc<TenzroNode>>,
    Path(instance_id): Path<String>,
) -> impl IntoResponse {
    // Try lookup by instance_id first, then by model_id
    let service = node.get_model_service(&instance_id)
        .or_else(|| node.find_model_service_by_model_id(&instance_id));

    if let Some(svc) = service {
        return (StatusCode::OK, Json(openai_model_entry(&node, &svc)));
    }

    // Gossip-discovered network model — same resolution the chat handler
    // uses, so anything routable is also inspectable.
    if let Some(entry) = node
        .network_models_snapshot()
        .into_iter()
        .find(|e| e.registration.model_id == instance_id)
    {
        return (
            StatusCode::OK,
            Json(openai_model_entry_from_registration(&node, &entry.registration)),
        );
    }

    (
        StatusCode::NOT_FOUND,
        Json(serde_json::json!({
            "error": {
                "message": format!("Model '{}' not found", instance_id),
                "type": "invalid_request_error",
                "code": "model_not_found"
            }
        })),
    )
}

/// OpenAI-compatible request body for `/v1/embeddings`.
///
/// `input` accepts either a single string or an array of strings, matching the
/// OpenAI spec. `dimensions` requests Matryoshka truncation on models that
/// support it (EmbeddingGemma, Qwen3-Embedding). `encoding_format` is accepted
/// for wire compatibility but only `float` is served — base64 packing is not.
#[derive(Debug, Deserialize)]
struct OpenAIEmbeddingsRequest {
    model: String,
    input: OpenAIEmbeddingInput,
    #[serde(default)]
    dimensions: Option<u32>,
    #[serde(default)]
    encoding_format: Option<String>,
    /// Tenzro extension: L2-normalize the output vectors. Off by default to
    /// match OpenAI, which returns already-normalized vectors from its own
    /// models but does not normalize on request. Retrieval pipelines that want
    /// unit vectors set this true.
    #[serde(default)]
    normalize: Option<bool>,
}

#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum OpenAIEmbeddingInput {
    Single(String),
    Batch(Vec<String>),
}

impl OpenAIEmbeddingInput {
    fn into_vec(self) -> Vec<String> {
        match self {
            OpenAIEmbeddingInput::Single(s) => vec![s],
            OpenAIEmbeddingInput::Batch(v) => v,
        }
    }
}

/// POST /v1/embeddings — OpenAI-compatible text embeddings.
///
/// Serves any encoder registered in this node's [`TextEmbeddingRuntime`]
/// (loaded via `tenzro_loadTextEmbeddingModel` / `tenzro embed-text load`).
/// Returns the OpenAI `{ object, data: [{ object, index, embedding }], model,
/// usage }` shape so drop-in OpenAI SDK clients work unchanged. Token usage is
/// not metered by the ORT encoder path, so `usage` fields report 0.
async fn handle_openai_embeddings(
    State(node): State<Arc<TenzroNode>>,
    Json(request): Json<OpenAIEmbeddingsRequest>,
) -> Response {
    if let Some(fmt) = request.encoding_format.as_deref()
        && !fmt.eq_ignore_ascii_case("float")
    {
        return openai_error_response(
            StatusCode::BAD_REQUEST,
            &format!("unsupported encoding_format '{fmt}' (only 'float' is served)"),
        );
    }

    let inputs = request.input.into_vec();
    if inputs.is_empty() {
        return openai_error_response(StatusCode::BAD_REQUEST, "'input' must be a non-empty string or array of strings");
    }

    let cfg = TextEmbedConfig {
        requested_dim: request.dimensions,
        normalize: request.normalize.unwrap_or(false),
    };

    let result = match node.text_embedding_runtime.embed(&request.model, inputs, cfg).await {
        Ok(r) => r,
        Err(e) => {
            return openai_error_response(
                StatusCode::BAD_REQUEST,
                &format!("embedding failed for model '{}': {}", request.model, e),
            );
        }
    };

    let data: Vec<Value> = result
        .embeddings
        .into_iter()
        .enumerate()
        .map(|(index, embedding)| {
            serde_json::json!({
                "object": "embedding",
                "index": index,
                "embedding": embedding,
            })
        })
        .collect();

    let body = serde_json::json!({
        "object": "list",
        "data": data,
        "model": request.model,
        "usage": { "prompt_tokens": 0, "total_tokens": 0 },
    });

    (StatusCode::OK, Json(body)).into_response()
}

/// Build an OpenAI-shaped error body: `{ error: { message, type } }`.
fn openai_error_response(status: StatusCode, message: &str) -> Response {
    let body = serde_json::json!({
        "error": { "message": message, "type": "invalid_request_error" }
    });
    (status, Json(body)).into_response()
}

/// POST /v1/chat/completions — OpenAI-compatible chat completions with SSE streaming
///
/// Supports resume via the SSE `Last-Event-ID` header. On reconnect the
/// client sets `Last-Event-ID: <completion_id>:<seq>`; if the cursor for
/// that completion is still in [`crate::streaming::StreamCursorStore`],
/// the handler replays any chunks with seq > `seq` and then either
/// closes (if the stream is already finished) or — for the still-in-flight
/// case — replays the tail. Live emission past the cursor's head is not
/// supported because the underlying `generate_chat_stream`
/// has no resume hook into the in-progress generation; for that, the
/// client should retry against a fresh prompt.
async fn handle_openai_chat_completions(
    State(node): State<Arc<TenzroNode>>,
    headers: HeaderMap,
    Json(request): Json<OpenAIChatRequest>,
) -> Response {
    let model_query = &request.model;
    let stream_requested = request.stream.unwrap_or(false);

    // ── SSE resume short-circuit ────────────────────────────────────────
    //
    // If the client sent `Last-Event-ID: <rid>:<seq>` and the cursor is
    // still alive, replay missed chunks and return without invoking the
    // model again. This is the *correct* shape for SSE resume per the
    // HTML5 spec (browsers auto-set this header on EventSource reconnect)
    // and matches what OpenAI/Anthropic SDK reconnect logic expects.
    if stream_requested {
        if let Some(hv) = headers.get("last-event-id")
            && let Ok(s) = hv.to_str()
            && let Some((rid, after_seq)) = crate::streaming::parse_last_event_id(s)
            && let Some((replay, finished)) = node.stream_cursors.replay(&rid, after_seq)
        {
            let replay_stream = async_stream::stream! {
                for chunk in replay {
                    yield Ok::<_, std::convert::Infallible>(
                        Event::default().id(format!("{}:{}", rid, chunk.seq)).data(chunk.encoded),
                    );
                }
                if finished {
                    yield Ok::<_, std::convert::Infallible>(
                        Event::default().data("[DONE]"),
                    );
                }
                // If not finished, the stream remains open; the client
                // will be holding it. We don't have a live tap into the
                // generator from a second request — that would need a
                // broadcast topology on the producer side. Document it.
            };
            return Sse::new(replay_stream)
                .keep_alive(axum::response::sse::KeepAlive::default())
                .into_response();
        }
    }

    // Resolve the model: try instance_id, then model_id in service registry, then served_models
    let mut service = node.get_model_service(model_query)
        .or_else(|| node.find_model_service_by_model_id(model_query));

    // Provider's iroh EndpointId for the network path (NAT-agnostic dispatch).
    // Populated only when the model is served by a remote peer.
    let mut net_iroh_endpoint_id: Option<String> = None;
    if service.is_none() && !node.served_models.contains_key(model_query) {
        let own_endpoint_id = node
            .iroh_resolver
            .as_ref()
            .map(|r| r.endpoint_id().to_string());
        for entry in node.network_models_snapshot() {
            let reg = &entry.registration;
            if reg.model_id.as_str() != model_query.as_str() {
                continue;
            }
            // Never resolve to our own announcement — that would dial our
            // own loopback endpoint.
            let is_self = own_endpoint_id.as_deref().is_some_and(|own| {
                !reg.iroh_endpoint_id.is_empty() && reg.iroh_endpoint_id == own
            });
            if is_self {
                continue;
            }
            net_iroh_endpoint_id = if reg.iroh_endpoint_id.is_empty() {
                None
            } else {
                Some(reg.iroh_endpoint_id.clone())
            };
            service = Some(tenzro_types::model::ModelServiceInstance {
                instance_id: format!("net-{}-{}", reg.model_id, reg.provider),
                model_id: reg.model_id.clone(),
                model_name: reg.name.clone(),
                provider_address: tenzro_types::primitives::Address::from_hex(&reg.provider)
                    .unwrap_or_default(),
                provider_name: reg.provider.clone(),
                location: tenzro_types::model::ModelLocation::Network,
                api_endpoint: reg.rpc_endpoint.clone(),
                mcp_endpoint: String::new(),
                status: tenzro_types::model::ServiceStatus::Online,
                parameters: reg.parameters.clone(),
                pricing: tenzro_types::model::PricingConfig {
                    price_per_input_token: reg.pricing.per_token.unwrap_or(0),
                    price_per_output_token: reg.pricing.per_token.unwrap_or(0),
                    minimum_price: reg.pricing.per_request,
                    pricing_model: tenzro_types::model::PricingModel::PerToken,
                },
                created_at: 0,
                last_seen: std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs(),
                load_info: None,
                iroh_endpoint_id: reg.iroh_endpoint_id.clone(),
            });
            break;
        }
    }

    // Determine if this is a local or network model
    let is_local = if let Some(ref svc) = service {
        svc.location == ModelLocation::Local
    } else {
        node.served_models.contains_key(model_query)
    };

    let model_id = if let Some(ref svc) = service {
        svc.model_id.clone()
    } else {
        model_query.clone()
    };

    if is_local {
        // === LOCAL MODEL ===
        let model_runtime = match node.model_runtime.as_ref() {
            Some(rt) => rt.clone(),
            None => {
                return json_error_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "Model runtime not initialized",
                    "server_error",
                    "runtime_unavailable",
                );
            }
        };

        if !model_runtime.is_loaded(&model_id) {
            return json_error_response(
                StatusCode::BAD_REQUEST,
                &format!("Model '{}' is not currently serving", model_id),
                "invalid_request_error",
                "model_not_loaded",
            );
        }

        let config = GenerationConfig {
            temperature: request.temperature.unwrap_or(0.7),
            top_p: request.top_p.unwrap_or(0.9),
            max_tokens: request.max_tokens.unwrap_or(512),
            repeat_penalty: 1.1,
            draft_n: request.draft_n.filter(|n| (1..=6).contains(n)),
            // Commitments require the buffered single-token path — the SSE
            // token channel cannot carry one, so streaming requests skip it.
            commitment_k: (!stream_requested && request.verifiable.unwrap_or(false))
                .then_some(tenzro_model::DEFAULT_COMMITMENT_K),
            ..GenerationConfig::default()
        };

        // Convert messages to model's ChatMessage format
        let chat_messages: Vec<ModelChatMessage> = request
            .messages
            .iter()
            .map(|m| ModelChatMessage {
                role: m.role.clone(),
                content: m.content.clone(),
            })
            .collect();

        if stream_requested {
            // === SSE STREAMING for local model ===
            let completion_id = format!("chatcmpl-{}", uuid::Uuid::new_v4());
            let created = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs();
            let model_id_clone = model_id.clone();
            let node_clone = node.clone();

            // Open a cursor for resume. Live emission below records each
            // chunk into the cursor in addition to yielding to the
            // client; a reconnecting client with `Last-Event-ID` replays
            // from this state.
            node.stream_cursors.create(&completion_id);
            let cursor_rid = completion_id.clone();

            // P1.3 SLO metrics — label the provider as "local" for
            // self-served models to keep label cardinality bounded.
            let slo = node.stream_slo_metrics.clone();
            let slo_provider = "local".to_string();
            let slo_model = model_id.clone();
            slo.record_stream_started(&slo_provider, &slo_model);
            let request_start = std::time::Instant::now();

            // P2.2 audit log — publish stream lifecycle events to the bus
            // so downstream consumers (replay, dispute resolution) see the
            // same start/first-token/drop/complete boundaries that the
            // SLO histograms record.
            let event_bus = node.event_bus.clone();
            let audit_request_id = completion_id.clone();
            let audit_model_id = model_id.clone();
            let audit_provider_label = slo_provider.clone();
            event_bus.publish(
                tenzro_events::TenzroEvent::InferenceStreamStarted {
                    request_id: audit_request_id.clone(),
                    model_id: audit_model_id.clone(),
                    provider_label: audit_provider_label.clone(),
                },
                None,
                Some(tenzro_events::VmType::Native),
            );

            let (token_tx, mut token_rx) = tokio::sync::mpsc::channel::<String>(256);

            // Spawn the generation task — it feeds tokens into token_tx
            let gen_model_id = model_id.clone();
            let gen_handle = tokio::spawn(async move {
                model_runtime
                    .generate_chat_stream(&gen_model_id, &chat_messages, &config, token_tx)
                    .await
            });

            // Build SSE stream from the token receiver
            let stream = async_stream::stream! {
                let cursors = node_clone.stream_cursors.clone();
                // P1.3 SLO timing state.
                let mut got_any_token = false;
                let mut last_token_at: Option<std::time::Instant> = None;
                // Emit each token as an OpenAI-compatible SSE chunk
                while let Some(token_piece) = token_rx.recv().await {
                    let now = std::time::Instant::now();
                    if !got_any_token {
                        let ttft = now.duration_since(request_start).as_secs_f64();
                        slo.record_first_token(&slo_provider, &slo_model, ttft);
                        event_bus.publish(
                            tenzro_events::TenzroEvent::InferenceStreamFirstToken {
                                request_id: audit_request_id.clone(),
                                model_id: audit_model_id.clone(),
                                provider_label: audit_provider_label.clone(),
                                ttft_ms: (ttft * 1000.0) as u64,
                            },
                            None,
                            Some(tenzro_events::VmType::Native),
                        );
                    } else if let Some(prev) = last_token_at {
                        let gap = now.duration_since(prev).as_secs_f64();
                        slo.record_intertoken(&slo_provider, &slo_model, gap);
                    }
                    last_token_at = Some(now);
                    got_any_token = true;
                    let chunk = serde_json::json!({
                        "id": &completion_id,
                        "object": "chat.completion.chunk",
                        "created": created,
                        "model": &model_id_clone,
                        "choices": [{
                            "index": 0,
                            "delta": {
                                "content": token_piece,
                            },
                            "finish_reason": null,
                        }]
                    });
                    // Raw JSON only — axum's Event::data() adds the
                    // `data:` line framing and terminating blank line.
                    let data = serde_json::to_string(&chunk).unwrap_or_default();
                    // Record into the cursor *before* yielding — keeps
                    // record and emit in lockstep so resume cannot miss
                    // a chunk the client already saw.
                    let seq = cursors.record(&cursor_rid, data.clone(), None).unwrap_or(0);
                    yield Ok::<_, std::convert::Infallible>(
                        Event::default().id(format!("{}:{}", cursor_rid, seq)).data(data),
                    );
                }

                // Wait for the generation result to get final stats
                let finish_reason = "stop";
                if let Ok(Ok(result)) = gen_handle.await {
                    // Emit the final chunk with finish_reason
                    let final_chunk = serde_json::json!({
                        "id": &completion_id,
                        "object": "chat.completion.chunk",
                        "created": created,
                        "model": &model_id_clone,
                        "choices": [{
                            "index": 0,
                            "delta": {},
                            "finish_reason": finish_reason,
                        }],
                        "usage": {
                            "prompt_tokens": result.input_tokens,
                            "completion_tokens": result.output_tokens,
                            "total_tokens": result.input_tokens + result.output_tokens,
                        }
                    });
                    let data = serde_json::to_string(&final_chunk).unwrap_or_default();
                    let seq = cursors.record(&cursor_rid, data.clone(), None).unwrap_or(0);
                    yield Ok::<_, std::convert::Infallible>(
                        Event::default().id(format!("{}:{}", cursor_rid, seq)).data(data),
                    );

                    // Emit the usage chunk with cost (wei). Shaped as an
                    // OpenAI `chat.completion.chunk` with empty `choices` —
                    // the `stream_options.include_usage` final-chunk shape —
                    // so strict SDK parsers accept it; the cost/throughput
                    // fields ride along as ignorable extensions.
                    // Scope the RwLock guard so it doesn't live across yield
                    let usage_data = {
                        let pricing = node_clone.provider_pricing.read();
                        let cost_wei = (result.input_tokens as u128)
                            .saturating_mul(pricing.input_price_per_token_wei)
                            .saturating_add(
                                (result.output_tokens as u128)
                                    .saturating_mul(pricing.output_price_per_token_wei),
                            );
                        serde_json::json!({
                            "id": &completion_id,
                            "object": "chat.completion.chunk",
                            "created": created,
                            "model": &model_id_clone,
                            "choices": [],
                            "usage": {
                                "prompt_tokens": result.input_tokens,
                                "completion_tokens": result.output_tokens,
                                "total_tokens": result.input_tokens + result.output_tokens,
                            },
                            "cost_wei": cost_wei.to_string(),
                            "generation_time_ms": result.generation_time_ms,
                            "tokens_per_second": result.tokens_per_second,
                        })
                    };
                    let data = serde_json::to_string(&usage_data).unwrap_or_default();
                    let seq = cursors.record(&cursor_rid, data.clone(), None).unwrap_or(0);
                    yield Ok::<_, std::convert::Infallible>(
                        Event::default().id(format!("{}:{}", cursor_rid, seq)).data(data),
                    );
                }

                // OpenAI-compatible stream terminator. The terminator is
                // not recorded into the cursor — replay always synthesizes
                // it from `finished == true` so a client resuming after a
                // completed stream still sees `[DONE]`.
                cursors.finish(&cursor_rid);
                // P1.3 completion observation: local-model channel closing
                // after at least one token is success; closing without any
                // token (rare — would mean the generator faulted before
                // emitting anything) is a failure for SLO purposes.
                slo.record_stream_completed(&slo_provider, &slo_model, got_any_token);
                let latency_ms = request_start.elapsed().as_millis() as u64;
                event_bus.publish(
                    tenzro_events::TenzroEvent::InferenceStreamCompleted {
                        request_id: audit_request_id.clone(),
                        model_id: audit_model_id.clone(),
                        provider_label: audit_provider_label.clone(),
                        latency_ms,
                        success: got_any_token,
                    },
                    None,
                    Some(tenzro_events::VmType::Native),
                );
                yield Ok::<_, std::convert::Infallible>(Event::default().data("[DONE]"));
            };

            Sse::new(stream)
                .keep_alive(axum::response::sse::KeepAlive::default())
                .into_response()
        } else {
            // === NON-STREAMING for local model ===
            match model_runtime.generate_chat(&model_id, &chat_messages, &config).await {
                Ok(result) => {
                    let pricing = node.provider_pricing.read();
                    let cost_wei = (result.input_tokens as u128)
                        .saturating_mul(pricing.input_price_per_token_wei)
                        .saturating_add(
                            (result.output_tokens as u128)
                                .saturating_mul(pricing.output_price_per_token_wei),
                        );

                    let completion_id = format!("chatcmpl-{}", uuid::Uuid::new_v4());

                    // Provider-side response signing: stamp a
                    // `tenzro_provenance` manifest signed with the node's
                    // long-term Ed25519 key so consumers (and routing nodes
                    // with `require_signed_response`) can verify this output
                    // against the announcement pubkey they pinned. Absent a
                    // signer, the response goes out unsigned — serving
                    // without attestation stays fully supported.
                    let provenance_manifest =
                        sign_local_response(&node, &model_id, result.text.as_bytes());

                    // TOPLOC commitment: persist and surface the hash when the
                    // caller sent `verifiable: true` and the serial path
                    // produced one; `null` otherwise (graceful degrade).
                    let commitment =
                        store_local_commitment(&node, &model_id, result.commitment.as_ref());

                    Json(serde_json::json!({
                        "id": completion_id,
                        "object": "chat.completion",
                        "created": std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_secs(),
                        "model": model_id,
                        "choices": [{
                            "index": 0,
                            "message": {
                                "role": "assistant",
                                "content": result.text,
                            },
                            "finish_reason": "stop"
                        }],
                        "usage": {
                            "prompt_tokens": result.input_tokens,
                            "completion_tokens": result.output_tokens,
                            "total_tokens": result.input_tokens + result.output_tokens,
                        },
                        "cost_wei": cost_wei.to_string(),
                        "generation_time_ms": result.generation_time_ms,
                        "tokens_per_second": result.tokens_per_second,
                        "tenzro_provenance": provenance_manifest,
                        "commitment": commitment,
                    }))
                    .into_response()
                }
                Err(e) => {
                    tracing::warn!(model = %model_id, error = %e, "Local inference failed");
                    json_error_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        &sanitize_model_error(&e),
                        "server_error",
                        "inference_error",
                    )
                }
            }
        }
    } else if let Some(ref svc) = service {
        // === NETWORK MODEL — forward to remote provider ===
        // A fast connect timeout means a loopback/unreachable `rpc_endpoint`
        // fails within seconds rather than pinning the caller on the default
        // (long) request timeout. No total-request timeout is set — a
        // legitimate SSE stream may run for minutes.
        let remote_url = format!("{}/chat/completions", svc.api_endpoint);
        let client = reqwest::Client::builder()
            .connect_timeout(std::time::Duration::from_secs(5))
            .build()
            .unwrap_or_else(|_| reqwest::Client::new());

        let forward_body = serde_json::json!({
            "model": svc.model_id,
            "messages": request.messages,
            "temperature": request.temperature,
            "max_tokens": request.max_tokens,
            "top_p": request.top_p,
            "stream": stream_requested,
            "draft_n": request.draft_n,
            // The remote provider persists the commitment and returns its
            // hash in the response body, which the non-streaming proxy path
            // passes through verbatim — challenges are filed against the
            // provider that served.
            "verifiable": request.verifiable,
        });

        if stream_requested {
            // === SSE STREAMING proxy for network model ===
            // Forward the request with stream:true and proxy the SSE response
            match client.post(&remote_url).json(&forward_body).send().await {
                Ok(resp) => {
                    if !resp.status().is_success() {
                        let status = resp.status();
                        let body = resp.text().await.unwrap_or_default();
                        return json_error_response(
                            StatusCode::from_u16(status.as_u16()).unwrap_or(StatusCode::BAD_GATEWAY),
                            &format!("Provider error: {}", body),
                            "server_error",
                            "provider_error",
                        );
                    }

                    // Open a cursor for this proxied stream so a client
                    // reconnect can resume against this gateway node. Each
                    // upstream byte-batch is recorded as one cursor chunk.
                    // The completion_id here is gateway-local — upstream
                    // OpenAI/Anthropic provider ids inside the chunks are
                    // pass-through.
                    let proxy_completion_id = format!("chatcmpl-proxy-{}", uuid::Uuid::new_v4());
                    node.stream_cursors.create(&proxy_completion_id);
                    let cursors = node.stream_cursors.clone();
                    let proxy_rid = proxy_completion_id.clone();

                    // Capture the provider address + provider_manager
                    // so a mid-stream drop can be charged back to the
                    // upstream provider via `record_stream_failure`.
                    // A pre-stream failure (non-2xx, connection refused)
                    // already returns early above and is the call-failure
                    // path; this branch is reached only after the upstream
                    // accepted the request and started writing the SSE.
                    let stream_provider_addr = svc.provider_address.clone();
                    let stream_provider_manager =
                        node.provider_manager().cloned();
                    let remote_url_for_log = remote_url.clone();
                    // P1.3 SLO metrics handle. Captured into the stream
                    // closure; observations on first-chunk (TTFT),
                    // every subsequent chunk (intertoken), and on stream
                    // termination (completed/failed counters).
                    let slo = node.stream_slo_metrics.clone();
                    let slo_provider = svc.provider_address.to_string();
                    let slo_model = svc.model_id.clone();
                    slo.record_stream_started(&slo_provider, &slo_model);
                    let request_start = std::time::Instant::now();

                    // P2.2 audit log — emit the same lifecycle events as
                    // the local path, with `provider_label` set to the
                    // remote provider's address string for label parity
                    // with the SLO histograms.
                    let event_bus = node.event_bus.clone();
                    let audit_request_id = proxy_rid.clone();
                    let audit_model_id = svc.model_id.clone();
                    let audit_provider_label = slo_provider.clone();
                    event_bus.publish(
                        tenzro_events::TenzroEvent::InferenceStreamStarted {
                            request_id: audit_request_id.clone(),
                            model_id: audit_model_id.clone(),
                            provider_label: audit_provider_label.clone(),
                        },
                        None,
                        Some(tenzro_events::VmType::Native),
                    );

                    // Proxy the SSE byte stream from the remote provider,
                    // wrapped in a heartbeat watchdog so a stuck-but-TCP-
                    // healthy provider gets caught at the application
                    // layer. With the defaults (5s × 2) we detect a stall
                    // within 10s — matches the P1.1 acceptance.
                    let byte_stream = resp.bytes_stream();
                    let stream = async_stream::stream! {
                        use crate::streaming::{with_heartbeat, HeartbeatConfig, HeartbeatedChunk};
                        use futures::StreamExt;
                        let mut bs = Box::pin(with_heartbeat(byte_stream, HeartbeatConfig::default()));
                        // Track whether any bytes were emitted before a
                        // drop, so we can distinguish "upstream accepted
                        // then died" (mid-stream drop, sharp signal) from
                        // "first chunk was already an error" (treat the
                        // same — the upstream told us yes then failed to
                        // deliver, that's the contract violation we
                        // penalize).
                        let mut got_any_chunk = false;
                        let mut had_stream_error = false;
                        let mut had_stall = false;
                        let mut stall_silent_for_ms: u64 = 0;
                        // P1.3 SLO timing state: when did the previous
                        // chunk land? Used to compute inter-chunk gap as
                        // a proxy for inter-token latency at the chunk
                        // granularity we observe (the upstream may pack
                        // multiple tokens per SSE event, but the gap is
                        // still the user-visible-update jitter).
                        let mut last_chunk_at: Option<std::time::Instant> = None;
                        // SSE re-framing buffer: the upstream sends raw
                        // pre-framed SSE bytes, but axum's Event::data()
                        // adds its own `data:` framing — forwarding the
                        // bytes verbatim would double-wrap every frame.
                        // Buffer until a complete frame boundary, extract
                        // the data payload, emit it raw.
                        let mut sse_buf = String::new();
                        while let Some(ev) = bs.next().await {
                            match ev {
                                HeartbeatedChunk::Chunk(Ok(bytes)) => {
                                    let now = std::time::Instant::now();
                                    if !got_any_chunk {
                                        // First-token observation.
                                        let ttft = now.duration_since(request_start).as_secs_f64();
                                        slo.record_first_token(&slo_provider, &slo_model, ttft);
                                        event_bus.publish(
                                            tenzro_events::TenzroEvent::InferenceStreamFirstToken {
                                                request_id: audit_request_id.clone(),
                                                model_id: audit_model_id.clone(),
                                                provider_label: audit_provider_label.clone(),
                                                ttft_ms: (ttft * 1000.0) as u64,
                                            },
                                            None,
                                            Some(tenzro_events::VmType::Native),
                                        );
                                    } else if let Some(prev) = last_chunk_at {
                                        let gap = now.duration_since(prev).as_secs_f64();
                                        slo.record_intertoken(&slo_provider, &slo_model, gap);
                                    }
                                    last_chunk_at = Some(now);
                                    got_any_chunk = true;
                                    sse_buf.push_str(
                                        &String::from_utf8_lossy(&bytes).replace("\r\n", "\n"),
                                    );
                                    while let Some(pos) = sse_buf.find("\n\n") {
                                        let frame: String = sse_buf.drain(..pos + 2).collect();
                                        let payload = frame
                                            .lines()
                                            .filter_map(|l| l.strip_prefix("data:"))
                                            .map(|l| l.strip_prefix(' ').unwrap_or(l))
                                            .collect::<Vec<_>>()
                                            .join("\n");
                                        if payload.is_empty() {
                                            // Comment/keepalive frame — nothing to forward.
                                            continue;
                                        }
                                        if payload == "[DONE]" {
                                            // Forward but don't record — replay
                                            // synthesizes [DONE] from finished.
                                            yield Ok::<_, std::convert::Infallible>(
                                                Event::default().data("[DONE]"),
                                            );
                                            continue;
                                        }
                                        let seq = cursors
                                            .record(&proxy_rid, payload.clone(), None)
                                            .unwrap_or(0);
                                        yield Ok::<_, std::convert::Infallible>(
                                            Event::default()
                                                .id(format!("{}:{}", proxy_rid, seq))
                                                .data(payload),
                                        );
                                    }
                                }
                                HeartbeatedChunk::Chunk(Err(e)) => {
                                    had_stream_error = true;
                                    warn!(
                                        "Mid-stream proxy error from {} (provider {}): {}",
                                        remote_url_for_log, stream_provider_addr, e
                                    );
                                    let err_json = serde_json::json!({
                                        "error": format!("Stream error: {}", e)
                                    });
                                    let text = serde_json::to_string(&err_json).unwrap_or_default();
                                    yield Ok::<_, std::convert::Infallible>(Event::default().data(text));
                                }
                                HeartbeatedChunk::Stalled { silent_for_ms } => {
                                    had_stall = true;
                                    stall_silent_for_ms = silent_for_ms;
                                    warn!(
                                        "Stream stalled (no chunks for {}ms) from {} (provider {})",
                                        silent_for_ms, remote_url_for_log, stream_provider_addr
                                    );
                                    let err_json = serde_json::json!({
                                        "error": format!(
                                            "Stream stalled: no tokens for {}ms",
                                            silent_for_ms
                                        )
                                    });
                                    let text = serde_json::to_string(&err_json).unwrap_or_default();
                                    yield Ok::<_, std::convert::Infallible>(Event::default().data(text));
                                }
                            }
                        }
                        // Flush a trailing partial frame — upstream closed
                        // without the final blank line.
                        let leftover = sse_buf
                            .lines()
                            .filter_map(|l| l.strip_prefix("data:"))
                            .map(|l| l.strip_prefix(' ').unwrap_or(l))
                            .collect::<Vec<_>>()
                            .join("\n");
                        if !leftover.is_empty() {
                            if leftover == "[DONE]" {
                                yield Ok::<_, std::convert::Infallible>(
                                    Event::default().data("[DONE]"),
                                );
                            } else {
                                let seq = cursors
                                    .record(&proxy_rid, leftover.clone(), None)
                                    .unwrap_or(0);
                                yield Ok::<_, std::convert::Infallible>(
                                    Event::default()
                                        .id(format!("{}:{}", proxy_rid, seq))
                                        .data(leftover),
                                );
                            }
                        }
                        // Charge the provider for a mid-stream drop or
                        // stall. We penalize on ANY stream error after the
                        // upstream returned 200 — by the time we got past
                        // the response headers the provider committed to
                        // delivering.
                        let latency_ms = request_start.elapsed().as_millis() as u64;
                        if had_stream_error || had_stall {
                            if let Some(pm) = &stream_provider_manager {
                                pm.record_stream_failure(&stream_provider_addr);
                            }
                            slo.record_stream_completed(&slo_provider, &slo_model, false);
                            let (reason, silent_for_ms) = if had_stall {
                                ("stall".to_string(), Some(stall_silent_for_ms))
                            } else {
                                ("upstream_error".to_string(), None)
                            };
                            event_bus.publish(
                                tenzro_events::TenzroEvent::InferenceStreamDropped {
                                    request_id: audit_request_id.clone(),
                                    model_id: audit_model_id.clone(),
                                    provider_label: audit_provider_label.clone(),
                                    reason,
                                    silent_for_ms,
                                },
                                None,
                                Some(tenzro_events::VmType::Native),
                            );
                        } else if got_any_chunk {
                            // Successful stream completion — reset the
                            // consecutive-stream-failure counter via the
                            // metrics record_success path with zero
                            // latency contribution (latency was already
                            // recorded per-token at the runtime side for
                            // local models; for proxied streams we don't
                            // observe per-token timing, so 0 is the
                            // honest value).
                            if let Some(pm) = &stream_provider_manager {
                                pm.record_success(&stream_provider_addr, 0);
                            }
                            slo.record_stream_completed(&slo_provider, &slo_model, true);
                        }
                        event_bus.publish(
                            tenzro_events::TenzroEvent::InferenceStreamCompleted {
                                request_id: audit_request_id.clone(),
                                model_id: audit_model_id.clone(),
                                provider_label: audit_provider_label.clone(),
                                latency_ms,
                                success: got_any_chunk && !had_stream_error && !had_stall,
                            },
                            None,
                            Some(tenzro_events::VmType::Native),
                        );
                        cursors.finish(&proxy_rid);
                    };

                    Sse::new(stream)
                        .keep_alive(axum::response::sse::KeepAlive::default())
                        .into_response()
                }
                Err(e) => json_error_response(
                    StatusCode::BAD_GATEWAY,
                    &format!("Failed to reach provider at {}: {}", remote_url, e),
                    "server_error",
                    "provider_unreachable",
                ),
            }
        } else {
            // === NON-STREAMING for network model ===
            // iroh-first (NAT-agnostic, addressed by the provider's advertised
            // EndpointId) with HTTP fallback to the announced `rpc_endpoint`.
            match forward_network_chat(
                &node,
                net_iroh_endpoint_id.as_deref(),
                &remote_url,
                &svc.provider_name,
                &forward_body,
            )
            .await
            {
                Ok(mut body) => {
                    // Best-effort verification of any provider-attached
                    // provenance manifest against the pinned announcement key.
                    // Invalid manifests are stripped so callers never see an
                    // unverified stamp.
                    if let Some(prov) = body
                        .get("tenzro_provenance")
                        .filter(|v| !v.is_null())
                        .cloned()
                    {
                        let content = body
                            .get("choices")
                            .and_then(|c| c.get(0))
                            .and_then(|c| c.get("message"))
                            .and_then(|m| m.get("content"))
                            .and_then(|v| v.as_str())
                            .unwrap_or("")
                            .to_string();
                        let pinned = pinned_announcement_pubkey(
                            &node,
                            &svc.model_id,
                            &svc.provider_name,
                        );
                        if verify_forwarded_provenance(
                            Some(&prov),
                            content.as_bytes(),
                            &svc.model_id,
                            pinned.as_deref(),
                            &svc.provider_name,
                        )
                        .is_none()
                            && let Some(obj) = body.as_object_mut()
                        {
                            obj.remove("tenzro_provenance");
                        }
                    }
                    (StatusCode::OK, Json(body)).into_response()
                }
                Err(e) => json_error_response(
                    StatusCode::BAD_GATEWAY,
                    &format!("Failed to reach provider: {}", e.message),
                    "server_error",
                    "provider_unreachable",
                ),
            }
        }
    } else {
        json_error_response(
            StatusCode::NOT_FOUND,
            &format!("Model '{}' not found. Use GET /v1/models to see available models.", model_query),
            "invalid_request_error",
            "model_not_found",
        )
    }
}

/// Build a JSON error response matching the OpenAI error format.
fn json_error_response(status: StatusCode, message: &str, error_type: &str, code: &str) -> Response {
    (
        status,
        Json(serde_json::json!({
            "error": {
                "message": message,
                "type": error_type,
                "code": code,
            }
        })),
    )
        .into_response()
}

/// Handle `POST /chat-stream` — Anthropic-style Server-Sent Events stream
/// for the rich-shape chat API.
///
/// Body is a JSON-RPC 2.0 envelope wrapping `tenzro_chatStream` params (the
/// same shape `tenzro_chat` accepts in its rich form). The response is a
/// `text/event-stream` carrying these events in order:
///
/// - `message_start` — once
/// - For each content block (text and/or tool_use):
///   - `content_block_start`
///   - one or more `content_block_delta` events (`text_delta` for text
///     blocks, `input_json_delta` for tool_use input)
///   - `content_block_stop`
/// - `message_delta` — once, carrying `stop_reason` and final `usage`
/// - `message_stop` — once, terminator
///
/// Per-token streaming for the rich shape is currently approximated: the
/// model generates synchronously and the resulting blocks are streamed
/// out as a single `*_delta` event per block. True token-level streaming
/// for the rich shape (interleaving with tool-call extraction) lands
/// when `ModelRuntime::generate_chat_with_tools_stream` is added.
pub async fn handle_chat_stream_rich(
    State(node): State<Arc<TenzroNode>>,
    Json(payload): Json<Value>,
) -> Response {
    use tenzro_types::model::{
        ContentBlock, RichChatMessage, SystemPrompt, ToolSchema,
    };

    // Pull params out of either a JSON-RPC envelope or a raw param object.
    let params: Value = if payload.get("jsonrpc").is_some() {
        payload.get("params").cloned().unwrap_or(Value::Null)
    } else {
        payload
    };

    let model_query = match params
        .get("model_id")
        .or_else(|| params.get("model"))
        .and_then(|v| v.as_str())
    {
        Some(s) => s.to_string(),
        None => {
            return json_error_response(
                StatusCode::BAD_REQUEST,
                "Missing 'model_id' (or 'model') parameter",
                "invalid_request_error",
                "missing_model",
            );
        }
    };

    // Parse messages — required for rich shape.
    let messages_value = match params.get("messages").cloned() {
        Some(v) => v,
        None => {
            return json_error_response(
                StatusCode::BAD_REQUEST,
                "Missing 'messages' parameter (rich shape required for /chat-stream)",
                "invalid_request_error",
                "missing_messages",
            );
        }
    };
    let messages: Vec<RichChatMessage> = match serde_json::from_value(messages_value.clone()) {
        Ok(m) => m,
        Err(e) => {
            return json_error_response(
                StatusCode::BAD_REQUEST,
                &format!("Invalid 'messages' shape: {}", e),
                "invalid_request_error",
                "invalid_messages",
            );
        }
    };
    if messages.is_empty() {
        return json_error_response(
            StatusCode::BAD_REQUEST,
            "'messages' must contain at least one message",
            "invalid_request_error",
            "empty_messages",
        );
    }
    if messages.len() > tenzro_types::validation::MAX_CHAT_MESSAGES {
        return json_error_response(
            StatusCode::BAD_REQUEST,
            &format!(
                "'messages' too many items: {} (max {})",
                messages.len(),
                tenzro_types::validation::MAX_CHAT_MESSAGES
            ),
            "invalid_request_error",
            "too_many_messages",
        );
    }
    for (i, m) in messages.iter().enumerate() {
        let len = m.payload_len();
        if len > tenzro_types::validation::MAX_CHAT_MESSAGE_LEN {
            return json_error_response(
                StatusCode::BAD_REQUEST,
                &format!(
                    "message[{}] content too long: {} bytes (max {})",
                    i, len, tenzro_types::validation::MAX_CHAT_MESSAGE_LEN
                ),
                "invalid_request_error",
                "message_too_long",
            );
        }
    }

    // Optional system + tools.
    let system: Option<SystemPrompt> = match params.get("system") {
        Some(v) => match serde_json::from_value(v.clone()) {
            Ok(s) => Some(s),
            Err(e) => {
                return json_error_response(
                    StatusCode::BAD_REQUEST,
                    &format!("Invalid 'system' shape: {}", e),
                    "invalid_request_error",
                    "invalid_system",
                );
            }
        },
        None => None,
    };
    let tools: Vec<ToolSchema> = match params.get("tools") {
        Some(v) => match serde_json::from_value(v.clone()) {
            Ok(t) => t,
            Err(e) => {
                return json_error_response(
                    StatusCode::BAD_REQUEST,
                    &format!("Invalid 'tools' shape: {}", e),
                    "invalid_request_error",
                    "invalid_tools",
                );
            }
        },
        None => Vec::new(),
    };
    for t in &tools {
        if !is_valid_tool_name(&t.name) {
            return json_error_response(
                StatusCode::BAD_REQUEST,
                &format!(
                    "Invalid tool name '{}': must match ^[a-zA-Z0-9_-]{{1,64}}$",
                    t.name
                ),
                "invalid_request_error",
                "invalid_tool_name",
            );
        }
        if !t.input_schema.is_object() {
            return json_error_response(
                StatusCode::BAD_REQUEST,
                &format!(
                    "Tool '{}' input_schema must be a JSON Schema object",
                    t.name
                ),
                "invalid_request_error",
                "invalid_tool_schema",
            );
        }
    }

    // Resolve the model service the same way the non-streaming path does.
    let mut service = node
        .get_model_service(&model_query)
        .or_else(|| node.find_model_service_by_model_id(&model_query));
    if service.is_none() && !node.served_models.contains_key(&model_query) {
        let own_endpoint_id = node
            .iroh_resolver
            .as_ref()
            .map(|r| r.endpoint_id().to_string());
        for entry in node.network_models_snapshot() {
            let reg = &entry.registration;
            if reg.model_id == model_query {
                // Never resolve to our own announcement — that would proxy
                // the SSE stream back into our own loopback endpoint.
                let is_self = own_endpoint_id.as_deref().is_some_and(|own| {
                    !reg.iroh_endpoint_id.is_empty() && reg.iroh_endpoint_id == own
                });
                if is_self {
                    continue;
                }
                service = Some(tenzro_types::model::ModelServiceInstance {
                    instance_id: format!("net-{}-{}", reg.model_id, reg.provider),
                    model_id: reg.model_id.clone(),
                    model_name: reg.name.clone(),
                    provider_address: tenzro_types::primitives::Address::from_hex(&reg.provider)
                        .unwrap_or_default(),
                    provider_name: reg.provider.clone(),
                    location: tenzro_types::model::ModelLocation::Network,
                    api_endpoint: reg.rpc_endpoint.clone(),
                    mcp_endpoint: String::new(),
                    status: tenzro_types::model::ServiceStatus::Online,
                    parameters: reg.parameters.clone(),
                    pricing: tenzro_types::model::PricingConfig {
                        price_per_input_token: reg.pricing.per_token.unwrap_or(0),
                        price_per_output_token: reg.pricing.per_token.unwrap_or(0),
                        minimum_price: reg.pricing.per_request,
                        pricing_model: tenzro_types::model::PricingModel::PerToken,
                    },
                    created_at: 0,
                    last_seen: std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_secs(),
                    load_info: None,
                    iroh_endpoint_id: reg.iroh_endpoint_id.clone(),
                });
                break;
            }
        }
    }

    let is_local = if let Some(ref svc) = service {
        svc.location == ModelLocation::Local
    } else {
        node.served_models.contains_key(&model_query)
    };

    let model_id = if let Some(ref svc) = service {
        svc.model_id.clone()
    } else {
        model_query.clone()
    };

    if !is_local {
        // Network forwarding for streaming rich shape would proxy the
        // remote provider's SSE byte stream verbatim (the same way
        // `/v1/chat/completions` does for OpenAI-shape). The current
        // landing only supports local serving.
        return json_error_response(
            StatusCode::NOT_IMPLEMENTED,
            "Rich-shape streaming for network-served models is not yet implemented; \
             use the non-streaming `tenzro_chat` rich shape, which forwards correctly.",
            "server_error",
            "stream_forward_unsupported",
        );
    }

    let model_runtime = match node.model_runtime.as_ref() {
        Some(rt) => rt.clone(),
        None => {
            return json_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Model runtime not initialized",
                "server_error",
                "runtime_unavailable",
            );
        }
    };

    if !model_runtime.is_loaded(&model_id) {
        return json_error_response(
            StatusCode::BAD_REQUEST,
            &format!("Model '{}' is not currently serving", model_id),
            "invalid_request_error",
            "model_not_loaded",
        );
    }

    let max_tokens = params
        .get("max_tokens")
        .and_then(|v| v.as_u64())
        .unwrap_or(1024);
    if tenzro_types::validation::validate_numeric_bound(
        max_tokens, "max_tokens", tenzro_types::validation::MAX_INFERENCE_TOKENS,
    ).is_err() {
        return json_error_response(
            StatusCode::BAD_REQUEST,
            &format!(
                "max_tokens exceeds maximum: {} (max {})",
                max_tokens, tenzro_types::validation::MAX_INFERENCE_TOKENS
            ),
            "invalid_request_error",
            "max_tokens_too_large",
        );
    }
    let max_tokens = max_tokens as u32;
    let temperature = params.get("temperature").and_then(|v| v.as_f64()).unwrap_or(0.7);
    if tenzro_types::validation::validate_temperature(temperature).is_err() {
        return json_error_response(
            StatusCode::BAD_REQUEST,
            &format!("temperature out of range: {} (must be 0.0..=2.0)", temperature),
            "invalid_request_error",
            "invalid_temperature",
        );
    }
    let config = GenerationConfig {
        temperature,
        top_p: params.get("top_p").and_then(|v| v.as_f64()).unwrap_or(0.9),
        max_tokens,
        repeat_penalty: params
            .get("repeat_penalty")
            .and_then(|v| v.as_f64())
            .unwrap_or(1.1) as f32,
        draft_n: params
            .get("draft_n")
            .and_then(|v| v.as_u64())
            .and_then(|n| u8::try_from(n).ok())
            .filter(|n| (1..=6).contains(n)),
        ..GenerationConfig::default()
    };

    // Flatten rich messages for the runtime (same as non-streaming path).
    let mut chat_messages: Vec<ModelChatMessage> = Vec::new();
    if let Some(sys) = &system {
        chat_messages.push(ModelChatMessage {
            role: "system".to_string(),
            content: sys.as_text(),
        });
    }
    for m in &messages {
        chat_messages.push(ModelChatMessage {
            role: m.role.clone(),
            content: render_blocks_as_text(&m.content),
        });
    }

    let runtime_tools: Vec<RuntimeToolDefinition> = tools
        .iter()
        .map(|t| RuntimeToolDefinition {
            name: t.name.clone(),
            description: if t.description.is_empty() {
                None
            } else {
                Some(t.description.clone())
            },
            input_schema: t.input_schema.clone(),
        })
        .collect();

    let message_id = format!("msg_{}", uuid::Uuid::new_v4().simple());
    let model_id_for_stream = model_id.clone();
    let node_for_stream = node.clone();
    let caller_address = params
        .get("caller_address")
        .and_then(|v| v.as_str())
        .map(String::from);

    let stream = async_stream::stream! {
        // Helper to emit a typed SSE event.
        macro_rules! sse_event {
            ($event:expr, $data:expr) => {{
                Ok::<_, std::convert::Infallible>(
                    Event::default().event($event).data(
                        serde_json::to_string(&$data).unwrap_or_else(|_| "{}".to_string()),
                    ),
                )
            }};
        }

        // ── message_start ────────────────────────────────────────────
        let start_payload = serde_json::json!({
            "id": message_id,
            "model": model_id_for_stream,
            "role": "assistant",
            "content": [],
            "usage": { "input_tokens": 0, "output_tokens": 0 },
        });
        yield sse_event!("message_start", start_payload);

        // ── run inference ────────────────────────────────────────────
        let gen_result = if !runtime_tools.is_empty() {
            model_runtime
                .generate_chat_with_tools(&model_id_for_stream, &chat_messages, &runtime_tools, &config)
                .await
        } else {
            // No tools: still go through the tool-aware path so the
            // event grammar stays uniform (extracts zero tool calls).
            model_runtime
                .generate_chat_with_tools(&model_id_for_stream, &chat_messages, &[], &config)
                .await
        };

        let result = match gen_result {
            Ok(r) => r,
            Err(e) => {
                tracing::warn!(model = %model_id_for_stream, error = %e, "Local inference failed");
                // Emit a synthetic error message_delta + message_stop so
                // the client can finalize cleanly.
                let err_payload = serde_json::json!({
                    "delta": { "stop_reason": "error", "stop_sequence": null },
                    "error": { "message": sanitize_model_error(&e), "type": "server_error" },
                    "usage": { "output_tokens": 0 },
                });
                yield sse_event!("message_delta", err_payload);
                yield sse_event!("message_stop", serde_json::json!({}));
                return;
            }
        };

        // Build the ordered block list: free text (if any) then each
        // tool_use in extraction order.
        let mut blocks: Vec<ContentBlock> = Vec::new();
        if !result.text.trim().is_empty() {
            blocks.push(ContentBlock::Text {
                text: result.text.clone(),
                cache_control: None,
            });
        }
        for tc in &result.tool_calls {
            blocks.push(ContentBlock::ToolUse {
                id: tc.id.clone(),
                name: tc.name.clone(),
                input: tc.input.clone(),
            });
        }
        if blocks.is_empty() {
            blocks.push(ContentBlock::Text {
                text: String::new(),
                cache_control: None,
            });
        }

        // ── per-block start / delta / stop ──────────────────────────
        for (idx, block) in blocks.iter().enumerate() {
            match block {
                ContentBlock::Text { text, .. } => {
                    let envelope = serde_json::json!({
                        "index": idx,
                        "content_block": { "type": "text", "text": "" },
                    });
                    yield sse_event!("content_block_start", envelope);

                    if !text.is_empty() {
                        let delta = serde_json::json!({
                            "index": idx,
                            "delta": { "type": "text_delta", "text": text },
                        });
                        yield sse_event!("content_block_delta", delta);
                    }

                    let stop = serde_json::json!({ "index": idx });
                    yield sse_event!("content_block_stop", stop);
                }
                ContentBlock::ToolUse { id, name, input } => {
                    let envelope = serde_json::json!({
                        "index": idx,
                        "content_block": {
                            "type": "tool_use",
                            "id": id,
                            "name": name,
                            "input": {},
                        },
                    });
                    yield sse_event!("content_block_start", envelope);

                    let partial_json = serde_json::to_string(input)
                        .unwrap_or_else(|_| "{}".to_string());
                    let delta = serde_json::json!({
                        "index": idx,
                        "delta": { "type": "input_json_delta", "partial_json": partial_json },
                    });
                    yield sse_event!("content_block_delta", delta);

                    let stop = serde_json::json!({ "index": idx });
                    yield sse_event!("content_block_stop", stop);
                }
                ContentBlock::Thinking { thinking } => {
                    let envelope = serde_json::json!({
                        "index": idx,
                        "content_block": { "type": "thinking", "thinking": "" },
                    });
                    yield sse_event!("content_block_start", envelope);

                    if !thinking.is_empty() {
                        let delta = serde_json::json!({
                            "index": idx,
                            "delta": { "type": "thinking_delta", "thinking": thinking },
                        });
                        yield sse_event!("content_block_delta", delta);
                    }

                    let stop = serde_json::json!({ "index": idx });
                    yield sse_event!("content_block_stop", stop);
                }
                _ => {
                    // Other block types (tool_result, image) are inputs
                    // only — never produced by the model.
                }
            }
        }

        // ── message_delta ────────────────────────────────────────────
        let stop_reason_str = map_stop_reason(&result.stop_reason);

        let delta_payload = serde_json::json!({
            "delta": {
                "stop_reason": stop_reason_str,
                "stop_sequence": serde_json::Value::Null,
            },
            "usage": {
                "input_tokens": result.input_tokens,
                "output_tokens": result.output_tokens,
            },
        });
        yield sse_event!("message_delta", delta_payload);

        // ── billing — same flow as the non-streaming rich path (wei) ─
        let cost_wei: u128 = {
            let pricing = node_for_stream.provider_pricing.read();
            (result.input_tokens as u128)
                .saturating_mul(pricing.input_price_per_token_wei)
                .saturating_add(
                    (result.output_tokens as u128)
                        .saturating_mul(pricing.output_price_per_token_wei),
                )
        };

        // Inside the SSE closure a JsonRpcError cannot be returned — surface
        // settlement failure as a terminal `error` event instead. The unpaid
        // record is still persisted for retry by the shared helper.
        match settle_inference_cost(
            &node_for_stream,
            caller_address.as_deref(),
            None,
            None,
            &model_id_for_stream,
            cost_wei,
        ) {
            Ok(_) => {}
            Err(e) => {
                yield sse_event!("error", serde_json::json!({
                    "type": "settlement_error",
                    "code": e.code,
                    "message": e.message,
                    "data": e.data,
                }));
            }
        }

        node_for_stream.metrics().record_inference();
        node_for_stream.touch_local_model_service(&model_id_for_stream);

        // ── message_stop ────────────────────────────────────────────
        yield sse_event!("message_stop", serde_json::json!({}));
    };

    Sse::new(stream)
        .keep_alive(axum::response::sse::KeepAlive::default())
        .into_response()
}

// === Model endpoint RPC handlers ===

async fn handle_list_model_endpoints(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let mut services = node.list_model_services();

    // Merge network-discovered model endpoints from gossipsub announcements.
    // Any node (validator, light client, RPC) can serve models. When they do,
    // they broadcast a ModelRegistration via gossipsub topic tenzro/models.
    // Receiving nodes store these in network_models. We include them here so that
    // tenzro_listModelEndpoints returns ALL endpoints visible to this node.
    let network_entries = node.network_models_snapshot();
    let local_model_ids: std::collections::HashSet<String> = services.iter().map(|s| s.model_id.clone()).collect();

    for entry in &network_entries {
        let reg = &entry.registration;
        // Skip if we already have a local entry for this model (avoid duplicates)
        if local_model_ids.contains(&reg.model_id) {
            continue;
        }
        services.push(tenzro_types::model::ModelServiceInstance {
            instance_id: format!("net-{}-{}", reg.model_id, reg.provider),
            model_id: reg.model_id.clone(),
            model_name: reg.name.clone(),
            provider_address: tenzro_types::primitives::Address::from_hex(&reg.provider).unwrap_or_default(),
            provider_name: reg.provider.clone(),
            location: tenzro_types::model::ModelLocation::Network,
            api_endpoint: reg.rpc_endpoint.clone(),
            mcp_endpoint: String::new(),
            status: tenzro_types::model::ServiceStatus::Online,
            parameters: reg.parameters.clone(),
            pricing: tenzro_types::model::PricingConfig {
                price_per_input_token: reg.pricing.per_token.unwrap_or(0),
                price_per_output_token: reg.pricing.per_token.unwrap_or(0),
                minimum_price: reg.pricing.per_request,
                pricing_model: tenzro_types::model::PricingModel::PerToken,
            },
            created_at: 0,
            last_seen: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
            load_info: None,
            iroh_endpoint_id: reg.iroh_endpoint_id.clone(),
        });
    }
    let entries: Vec<Value> = services
        .iter()
        .map(|svc| {
            let mut entry = serde_json::json!({
                "instance_id": svc.instance_id,
                "model_id": svc.model_id,
                "model_name": svc.model_name,
                "provider_name": svc.provider_name,
                "location": svc.location.to_string(),
                "api_endpoint": svc.api_endpoint,
                "mcp_endpoint": svc.mcp_endpoint,
                "iroh_endpoint_id": svc.iroh_endpoint_id,
                "status": svc.status.to_string(),
                "parameters": svc.parameters,
                "pricing": {
                    "input": svc.pricing.price_per_input_token,
                    "output": svc.pricing.price_per_output_token,
                },
                "created_at": svc.created_at,
            });

            // Add load info for tracked models
            if let Some(snap) = node.load_tracker.snapshot(&svc.model_id) {
                entry["load"] = serde_json::json!({
                    "active_requests": snap.active_requests,
                    "max_concurrent": snap.max_concurrent,
                    "utilization_percent": snap.utilization_percent,
                    "load_level": snap.load_level.to_string(),
                });
            }

            // Surface the backing engine when this model is served through an
            // external OpenAI-compatible endpoint (vLLM / SGLang / etc.).
            if let Some(runtime) = node.model_runtime.as_ref()
                && let Some((kind, base_url, upstream_model)) =
                    runtime.external_engine_info(&svc.model_id)
            {
                entry["engine"] = serde_json::json!({
                    "kind": kind,
                    "base_url": base_url,
                    "upstream_model": upstream_model,
                });
            }

            entry
        })
        .collect();

    Ok(Value::Array(entries))
}

async fn handle_get_model_endpoint(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    // Support lookup by instance_id or model_id
    let query = params
        .get("instance_id")
        .or_else(|| params.get("model_id"))
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'instance_id' or 'model_id' parameter".to_string(),
            data: None,
        })?;

    let service = node.get_model_service(query)
        .or_else(|| node.find_model_service_by_model_id(query));

    match service {
        Some(svc) => Ok(serde_json::json!({
            "instance_id": svc.instance_id,
            "model_id": svc.model_id,
            "model_name": svc.model_name,
            "provider_name": svc.provider_name,
            "location": svc.location.to_string(),
            "api_endpoint": svc.api_endpoint,
            "mcp_endpoint": svc.mcp_endpoint,
            "iroh_endpoint_id": svc.iroh_endpoint_id,
            "status": svc.status.to_string(),
            "parameters": svc.parameters,
            "pricing": {
                "input": svc.pricing.price_per_input_token,
                "output": svc.pricing.price_per_output_token,
            },
            "created_at": svc.created_at,
        })),
        None => Err(JsonRpcError {
            code: -32000,
            message: format!("Model endpoint not found: {}", query),
            data: None,
        }),
    }
}

async fn handle_register_model_endpoint(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let model_id = params
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'model_id' parameter".to_string(),
            data: None,
        })?;

    let api_endpoint = params
        .get("api_endpoint")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'api_endpoint' parameter".to_string(),
            data: None,
        })?;

    let mcp_endpoint = params
        .get("mcp_endpoint")
        .and_then(|v| v.as_str())
        .unwrap_or("");

    let model_name = params
        .get("model_name")
        .and_then(|v| v.as_str())
        .unwrap_or(model_id);

    let provider_name = params
        .get("provider_name")
        .and_then(|v| v.as_str())
        .unwrap_or("Network Provider");

    let parameters = params
        .get("parameters")
        .and_then(|v| v.as_str())
        .unwrap_or("");

    let instance_id = node.register_model_service(
        model_id,
        model_name,
        provider_name,
        ModelLocation::Network,
        api_endpoint,
        mcp_endpoint,
        parameters,
    );

    Ok(serde_json::json!({
        "success": true,
        "instance_id": instance_id,
        "model_id": model_id,
        "location": "network",
        "api_endpoint": api_endpoint,
        "mcp_endpoint": mcp_endpoint,
    }))
}

async fn handle_unregister_model_endpoint(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let instance_id = params
        .get("instance_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing 'instance_id' parameter".to_string(),
            data: None,
        })?;

    node.unregister_model_service(instance_id);

    Ok(serde_json::json!({
        "success": true,
        "instance_id": instance_id,
        "status": "unregistered",
    }))
}

